                try { input = Console.ReadLine(); }
                catch { return; }
                if (string.IsNullOrWhiteSpace(input)) return;
                int n;
                if (int.TryParse(input.Trim(), out n))
                {
                    if (n == 1)
                    {
                        int s = ShowStrategyMenu();
                        if (s >= 0) { strategy = s; WriteStrategyFile(strategy); ApplyConfluxPresetForStrategy(strategy); }
                    }
                    else if (n == 2) { PromptConfluxSets(); }
                    else if (n == 3) { PromptConfluxLegs(); }
                    else if (n == 4) { PromptConfluxLinkedSets(); }
                    else if (n == 5)
                    {
                        keepAliveEnabled = !keepAliveEnabled;
                        WriteKeepAliveFile(keepAliveEnabled);
                    }
                    else if (n == 6) { PromptConfluxSelection(); }
                    else if (n == 7) { PromptConfluxRttMax(); }
                    else if (n == 8) { PromptConfluxRttPct(); }
                    else if (n == 9) { PromptWatchRttPct(); }
                    else if (n == 10) return;
                    else Console.WriteLine("  Invalid choice, try again.");
                }
                else Console.WriteLine("  Invalid choice, try again.");
            }
        }

        // Builds the torrc content for a mode/strategy (template + bridges +
        // strategy + conflux blocks). Returns null when the template or the
        // bridge file is missing (reason already printed).
        private static string BuildTorrc(int mode, int strategy, out int bridgeCount)
        {
            bridgeCount = 0;
            if (!File.Exists(TorrcTemplate))
            {
                Console.WriteLine("[x] torrc.template not found in " + DataDir);
                return null;
            }
            string tmpl = File.ReadAllText(TorrcTemplate);
            StringBuilder sb = new StringBuilder(tmpl.TrimEnd());
            if (BridgeFiles[mode].Length > 0)
            {
                string bf = Path.Combine(BridgesDir, BridgeFiles[mode]);
                if (!File.Exists(bf))
                {
                    Console.WriteLine("[x] bridge file not found: " + bf);
                    return null;
                }
                var bridges = new List<string>();
                foreach (string line in File.ReadAllLines(bf))
                {
                    string t = line.Trim();
                    if (t.Length == 0 || t.StartsWith("#")) continue;
                    bridges.Add("Bridge " + t);
                }
                if (bridges.Count == 0)
                {
                    Console.WriteLine("[!] no usable bridge lines in " + bf);
                    return null;
                }
                sb.AppendLine();
                sb.AppendLine();
                sb.AppendLine("# --- bridges: " + ModeNames[mode] + " ---");
                sb.AppendLine("UseBridges 1");
                foreach (string b in bridges) sb.AppendLine(b);
                bridgeCount = bridges.Count;
            }
            if (strategy >= 0 && strategy < StrategyNames.Length && StrategyTorrc[strategy].Length > 0)
            {
                sb.AppendLine();
                sb.AppendLine();
                sb.AppendLine("# --- strategy: " + StrategyNames[strategy] + " ---");
                foreach (string line in StrategyTorrc[strategy]) sb.AppendLine(line);
            }
            if (confluxSets > 0)
            {
                sb.AppendLine();
                sb.AppendLine();
                sb.AppendLine("# --- conflux: " + confluxSets + " set(s) ---");
                sb.AppendLine("ConfluxNumSets " + confluxSets);
            }
            if (confluxLinkedSets > 0)
            {
                sb.AppendLine();
                sb.AppendLine();
                sb.AppendLine("# --- conflux: linked-set cap " + confluxLinkedSets + " ---");
                sb.AppendLine("ConfluxNumLinkedSets " + confluxLinkedSets);
            }
            if (confluxLegs > 0)
            {
                sb.AppendLine();
                sb.AppendLine();
                sb.AppendLine("# --- conflux: " + confluxLegs + " leg(s) per set ---");
                sb.AppendLine("ConfluxNumLegs " + confluxLegs);
            }
            if (confluxSelection >= 0 && confluxSelection < SetSelectionNames.Length)
            {
                sb.AppendLine();
                sb.AppendLine();
                sb.AppendLine("# --- conflux: set selection " + SetSelectionNames[confluxSelection] + " ---");
                sb.AppendLine("ConfluxSetSelection " + confluxSelection);
            }
            if (confluxRttMax > 0)
            {
                sb.AppendLine();
                sb.AppendLine();
                sb.AppendLine("# --- conflux: skip sets slower than " + confluxRttMax + " ms ---");
                sb.AppendLine("ConfluxSetRttMax " + confluxRttMax);
            }
            if (confluxRttPct > 0)
            {
                sb.AppendLine();
                sb.AppendLine();
                sb.AppendLine("# --- conflux: keep best " + confluxRttPct + "% of sets by RTT ---");
                sb.AppendLine("ConfluxSetRttPct " + confluxRttPct);
            }
            return sb.ToString();
        }

        private static bool WriteTorrc(int mode, int strategy)
        {
            int bridgeCount;
            string content = BuildTorrc(mode, strategy, out bridgeCount);
            if (content == null) return false;
            File.WriteAllText(Torrc, content, new UTF8Encoding(false));
            try { File.WriteAllText(ModeFile, ModeNames[mode], new UTF8Encoding(false)); }
            catch { }
            try { WriteStrategyFile(strategy); }
            catch { }
            Console.WriteLine("torrc written (" + ModeNames[mode] +
                              ", strategy " + StrategyNames[strategy] +
                              (BridgeFiles[mode].Length > 0 ? ", " + bridgeCount + " bridges" : "") +
                              (confluxSets > 0 ? ", " + confluxSets + " sets" : "") +
                              (confluxLinkedSets > 0 ? ", cap " + confluxLinkedSets : "") +
                              (confluxLegs > 0 ? ", " + confluxLegs + " legs/set" : "") +
                              (confluxSelection > 0 ? ", select " + SetSelectionNames[confluxSelection] : "") +
                              (confluxRttMax > 0 ? ", skip " + confluxRttMax + "ms" : "") +
                              (confluxRttPct > 0 ? ", top " + confluxRttPct + "%" : "") + ")");
            Log("torrc written (" + ModeNames[mode] + ", strategy " +
                StrategyNames[strategy] + ", " + bridgeCount + " bridges, " +
                confluxSets + " sets, cap " +
                confluxLinkedSets + ", " + confluxLegs + " legs/set, select " +
                SetSelectionNames[confluxSelection] + ", skip " + confluxRttMax + "ms" +
                (confluxRttPct > 0 ? ", top " + confluxRttPct + "%" : "") + ")");
            return true;
        }

        private static int CountBridgeLines(string path)
        {
            int n = 0;
            foreach (string line in File.ReadAllLines(path))
            {
                string t = line.Trim();
                if (t.Length == 0 || t.StartsWith("#")) continue;
                if (t.Contains("2001:db8")) continue;
                n++;
            }
            return n;
        }

        private static int UpdateBridges()
        {
            try
            {
                ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;
            }
            catch { }

            Directory.CreateDirectory(BridgesDir);
            Console.WriteLine("Updating bridge files from " + BridgesBaseUrl);
            Console.WriteLine("  -> " + BridgesDir);
            Console.WriteLine();

            int ok = 0;
            foreach (string f in AllBridgeFiles)
            {
                string dest = Path.Combine(BridgesDir, f);
                string tmp = dest + ".tmp";
                string url = BridgesBaseUrl + "/" + f;
                try
                {
                    using (WebClient wc = new WebClient())
                    {
                        wc.Headers[HttpRequestHeader.UserAgent] = "torjet-updater/1.0";
                        wc.DownloadFile(url, tmp);
                    }
                    int n = CountBridgeLines(tmp);
                    if (n == 0)
                    {
                        Console.WriteLine("[!] " + f + ": downloaded file has no usable bridges - keeping old.");
                        try { File.Delete(tmp); } catch { }
                        continue;
                    }
                    File.Copy(tmp, dest, true);
                    try { File.Delete(tmp); } catch { }
                    Console.WriteLine("" + f + ": " + n + " bridges - updated.");
                    ok++;
                }
                catch (Exception ex)
                {
                    Console.WriteLine("[x] " + f + ": " + ex.Message);
                }
            }

            Console.WriteLine();
            if (ok == AllBridgeFiles.Length)
            {
                Console.WriteLine("All bridge files are up to date.");
                return 0;
            }
            Console.WriteLine("Updated " + ok + " of " + AllBridgeFiles.Length +
                              " bridge files (restart tor to use the new bridges).");
            return ok > 0 ? 0 : 1;
        }

        private static string FormatSpeed(double bytesPerSec)
        {
            if (bytesPerSec >= 1024 * 1024)
                return (bytesPerSec / (1024 * 1024)).ToString("0.00") + " MB/s";
            if (bytesPerSec >= 1024)
                return (bytesPerSec / 1024).ToString("0.0") + " KB/s";
            return bytesPerSec.ToString("0") + " B/s";
        }

        private static void SpeedTest()
        {
            try { ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12; }
            catch { }

            Console.WriteLine();
            Console.WriteLine("Speed test: downloading 10 MB through Tor (HTTP 127.0.0.1:8118)...");
            try
            {
                HttpWebRequest req = (HttpWebRequest)WebRequest.Create(
                    "https://speed.cloudflare.com/__down?bytes=10000000");
                req.Proxy = new WebProxy("127.0.0.1", 8118);
                req.Method = "GET";
                req.Timeout = 60000;
                req.ReadWriteTimeout = 60000;
                req.UserAgent = "torjet-speedtest/1.0";

                using (WebResponse resp = req.GetResponse())
                using (Stream s = resp.GetResponseStream())
                {
                    byte[] buf = new byte[64 * 1024];
                    long total = 0;
                    Stopwatch sw = Stopwatch.StartNew();
                    long lastBytes = 0;
                    long lastTicks = sw.ElapsedTicks;
                    double inst = 0;
                    int n;
                    while ((n = s.Read(buf, 0, buf.Length)) > 0)
                    {
                        total += n;
                        long now = sw.ElapsedTicks;
                        if (now - lastTicks >= Stopwatch.Frequency)
                        {
                            inst = (total - lastBytes) /
                                   ((now - lastTicks) / (double)Stopwatch.Frequency);
                            lastBytes = total;
                            lastTicks = now;
                            Console.WriteLine("    " + total.ToString("#,0") + " bytes  (" + FormatSpeed(inst) + ")");
                        }
                    }
                    sw.Stop();

                    if (total > lastBytes)
                        inst = (total - lastBytes) /
                               ((sw.ElapsedTicks - lastTicks) / (double)Stopwatch.Frequency);
                    double avg = total / sw.Elapsed.TotalSeconds;

                    Console.WriteLine();
                    Console.WriteLine("Done: " + total.ToString("#,0") + " bytes in " +
                                      sw.Elapsed.TotalSeconds.ToString("0.0") + " s");
                    Console.WriteLine("  average speed    : " + FormatSpeed(avg));
                    Console.WriteLine("  instantaneous    : " + FormatSpeed(inst));
                    Console.WriteLine("  (avg MB/s = " + (avg / (1024 * 1024)).ToString("0.00") + ")");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("[x] speed test failed: " + ex.Message);
            }
        }

        // Opens a raw SOCKS5 (RFC 1928) connection through Tor's SOCKS port
        // (127.0.0.1:9050). A unique `username` per connection makes tor's
        // IsolateSOCKSAuth isolation give every stream its own circuit, which is
        // what turns N parallel downloads into N parallel Tor paths instead of
        // N streams sharing one circuit.
        private static NetworkStream Socks5Connect(string host, int port, string username)
        {
            TcpClient tc = new TcpClient();
            tc.Connect(IPAddress.Loopback, 9050);
            NetworkStream ns = tc.GetStream();
            ns.ReadTimeout = 90000;
            ns.WriteTimeout = 90000;
            // greeting: VER=5, NMETHODS=2, methods = no-auth(0), user/pass(2)
            byte[] g = { 5, 2, 0, 2 };
            ns.Write(g, 0, g.Length);
            byte[] gm = new byte[2];
            if (ns.Read(gm, 0, 2) != 2 || gm[0] != 5) { tc.Close(); return null; }
            if (gm[1] == 2)
            {
                byte[] u = Encoding.UTF8.GetBytes(username);
                byte[] p = Encoding.UTF8.GetBytes("torb");
                ns.WriteByte(1);
                ns.WriteByte((byte)u.Length);
                ns.Write(u, 0, u.Length);
                ns.WriteByte((byte)p.Length);
                ns.Write(p, 0, p.Length);
                byte[] au = new byte[2];
                if (ns.Read(au, 0, 2) != 2 || au[1] != 0) { tc.Close(); return null; }
            }
            else if (gm[1] != 0)
            {
                tc.Close();
                return null;
            }
            byte[] hb = Encoding.ASCII.GetBytes(host);
            List<byte> req = new List<byte>();
            req.Add(5); req.Add(1); req.Add(0); req.Add(3); req.Add((byte)hb.Length);
            req.AddRange(hb);
            req.Add((byte)(port >> 8)); req.Add((byte)(port & 0xff));
            byte[] rq = req.ToArray();
            ns.Write(rq, 0, rq.Length);
            byte[] rh = new byte[4];
            if (ns.Read(rh, 0, 4) != 4 || rh[0] != 5 || rh[1] != 0) { tc.Close(); return null; }
            int atyp = rh[3];
            int skip = atyp == 1 ? 6 : atyp == 4 ? 18 : 0;
            if (atyp == 3) { skip = ns.ReadByte() + 2; }
            for (int i = 0; i < skip; i++) ns.ReadByte();
            return ns;
        }

        // Downloads `bytes` from host over a freshly established SOCKS5 stream
        // (username gives it an isolated circuit). Returns bytes received.
        private static long SocksDownload(string host, string username, long bytes)
        {
            try
            {
                NetworkStream ns = Socks5Connect(host, 443, username);
                if (ns == null) return -1;
                using (var ssl = new System.Net.Security.SslStream(ns))
                {
                    ssl.ReadTimeout = 90000;
                    ssl.WriteTimeout = 90000;
                    ssl.AuthenticateAsClient(host, null,
                        System.Security.Authentication.SslProtocols.Tls12, false);
                    byte[] req = Encoding.ASCII.GetBytes(
                        "GET /__down?bytes=" + bytes + " HTTP/1.1\r\n" +
                        "Host: " + host + "\r\n" +
                        "User-Agent: torjet-speedtest/1.0\r\n" +
                        "Connection: close\r\n\r\n");
                    ssl.Write(req, 0, req.Length);
                    ssl.Flush();
                    byte[] buf = new byte[64 * 1024];
                    long total = 0;
                    int n;
                    while ((n = ssl.Read(buf, 0, buf.Length)) > 0) total += n;
                    return total;
                }
            }
            catch { return -1; }
        }

        // Uploads `bytes` to host over a freshly established SOCKS5 stream
        // (username gives it an isolated circuit). Returns bytes sent when the
        // server answered 2xx, otherwise -1.
        private static long SocksUpload(string host, string username, long bytes)
        {
            try
            {
                NetworkStream ns = Socks5Connect(host, 443, username);
                if (ns == null) return -1;
                using (var ssl = new System.Net.Security.SslStream(ns))
                {
                    ssl.ReadTimeout = 180000;
                    ssl.WriteTimeout = 180000;
                    ssl.AuthenticateAsClient(host, null,
                        System.Security.Authentication.SslProtocols.Tls12, false);
                    byte[] head = Encoding.ASCII.GetBytes(
                        "POST /__up HTTP/1.1\r\n" +
                        "Host: " + host + "\r\n" +
                        "User-Agent: torjet-speedtest/1.0\r\n" +
                        "Content-Type: application/octet-stream\r\n" +
                        "Content-Length: " + bytes + "\r\n" +
                        "Connection: close\r\n\r\n");
                    ssl.Write(head, 0, head.Length);
                    ssl.Flush();
                    byte[] buf = new byte[64 * 1024]; // zero payload; the endpoint discards it
                    long sent = 0;
                    while (sent < bytes)
                    {
                        int chunk = (int)Math.Min((long)buf.Length, bytes - sent);
                        ssl.Write(buf, 0, chunk);
                        sent += chunk;
                    }
                    byte[] rb = new byte[4096];
                    StringBuilder resp = new StringBuilder();
                    int r;
                    while ((r = ssl.Read(rb, 0, rb.Length)) > 0 && resp.Length < 8192)
                        resp.Append(Encoding.ASCII.GetString(rb, 0, r));
                    string s = resp.ToString();
                    int sp = s.IndexOf(' ');
                    if (sp < 1 || s.Length < sp + 4) return -1;
                    int code;
                    if (!int.TryParse(s.Substring(sp + 1, 3), out code)) return -1;
                    return (code >= 200 && code < 300) ? sent : -1;
                }
            }
            catch { return -1; }
        }

        private const string SpeedHost = "speed.cloudflare.com";
        private const long SpeedBytesPerStream = 10L * 1024 * 1024;
        // Last measured aggregate averages, for the GUI stats panel.
        private static double lastDownBps;
        private static double lastUpBps;

        // Runs `streams` parallel isolated-circuit transfers (download or
        // upload) of SpeedBytesPerStream each and prints the aggregate result.
        private static void ParallelTransfer(int streams, bool upload)
        {
            string dir = upload ? "up" : "down";
            Console.WriteLine();
            Console.WriteLine("Max " + dir + " test: " + streams + " parallel streams " +
                              "(each on its own circuit via SOCKS5 auth)...");
            long total = 0;
            var lockObj = new object();
            var errors = new List<string>();
            var threads = new List<Thread>();
            Stopwatch sw = Stopwatch.StartNew();
            for (int i = 0; i < streams; i++)
            {
                string user = "torb" + i; // unique -> isolated circuit
                Thread th = new Thread(delegate()
                {
                    long got = upload ? SocksUpload(SpeedHost, user, SpeedBytesPerStream)
                                      : SocksDownload(SpeedHost, user, SpeedBytesPerStream);
                    if (got < 0)
                    {
                        lock (lockObj) { if (errors.Count == 0) errors.Add("stream " + user + " failed"); }
                        got = 0;
                    }
                    Interlocked.Add(ref total, got);
                });
                th.IsBackground = true;
                threads.Add(th);
                th.Start();
            }
            foreach (Thread th in threads) th.Join();
            sw.Stop();
            double avg = total / sw.Elapsed.TotalSeconds;
            if (upload) lastUpBps = avg; else lastDownBps = avg;
            Console.WriteLine("Done (" + dir + "): " + total.ToString("#,0") + " bytes in " +
                              sw.Elapsed.TotalSeconds.ToString("0.0") + " s");
            Console.WriteLine("  aggregate average : " + FormatSpeed(avg));
            if (errors.Count > 0) Console.WriteLine("  " + errors.Count + " of " + streams + " streams failed");
        }

        private static void MultiSpeedTest(int streams, bool includeUp)
        {
            ParallelTransfer(streams, false);
            if (includeUp) ParallelTransfer(streams, true);
        }

        private static void SpeedTestMenu()
        {
            Console.WriteLine();
            Console.WriteLine("  Speed test:");
            Console.WriteLine("    1) Single stream down (HTTP 8118)");
            Console.WriteLine("    2) Max down: " + MaxSpeedTestStreams +
                              " parallel SOCKS5 streams, each own circuit");
            Console.WriteLine("    3) Max up:   " + MaxSpeedTestStreams +
                              " parallel SOCKS5 streams, each own circuit");
            Console.WriteLine("    4) Max both: down + up");
            Console.Write("  Choose 1-4 (Enter = 4): ");
            string input;
            try { input = Console.ReadLine(); }
            catch { input = "4"; }
            if (string.IsNullOrWhiteSpace(input)) input = "4";
            int n;
            if (!int.TryParse(input.Trim(), out n)) n = 4;
            if (n == 1) SpeedTest();
            else if (n == 2) ParallelTransfer(MaxSpeedTestStreams, false);
            else if (n == 3) ParallelTransfer(MaxSpeedTestStreams, true);
            else MultiSpeedTest(MaxSpeedTestStreams, true);
        }

        // --- benchmark / conflux diagnostics (step 0 harness) --------------

        private static byte[] HexToBytes(string hex)
        {
            byte[] b = new byte[hex.Length / 2];
            for (int i = 0; i < b.Length; i++)
                b[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
            return b;
        }

        // Sends a command to the tor control port and returns every raw reply
        // line, including the terminating status line ("250 OK" and friends).
        // Returns null when the port is unreachable or auth fails.
        private static List<string> ControlRaw(string cmd)
        {
            return ControlRawFor(9051, cmd, ControlCookie);
        }

        private static List<string> ControlRawFor(int port, string cmd, string cookiePath)
        {
            try
            {
                string hex = CookieHexFor(cookiePath);
                if (hex == null) return null;
                using (TcpClient c = new TcpClient("127.0.0.1", port))
                {
                    NetworkStream s = c.GetStream();
                    s.ReadTimeout = 5000;
                    StreamWriter w = new StreamWriter(s) { NewLine = "\r\n", AutoFlush = true };
                    StreamReader r = new StreamReader(s);
                    w.WriteLine("AUTHENTICATE " + hex);
                    string a = r.ReadLine();
                    if (a == null || !a.StartsWith("250")) return null;
                    w.WriteLine(cmd);
                    var lines = new List<string>();
                    string line;
                    while ((line = r.ReadLine()) != null)
                    {
                        lines.Add(line);
                        // A reply ends at any status line: "250 OK", "250 ...",
                        // or an error line like "510 ...", "552 ...".
                        if (line.Length >= 4 && line[0] >= '0' && line[0] <= '9' &&
                            line[1] >= '0' && line[1] <= '9' &&
                            line[2] >= '0' && line[2] <= '9' && line[3] == ' ')
                            break;
                    }
                    try { w.WriteLine("QUIT"); } catch { }
                    return lines;
                }
            }
            catch { return null; }
        }

        // Sends a command to the tor control port and returns the response
        // payload lines (without the terminating status line).
        private static List<string> ControlCommand(string cmd)
        {
            return ControlCommandFor(9051, cmd, ControlCookie);
        }

        private static List<string> ControlCommandFor(int port, string cmd, string cookiePath)
        {
            var raw = ControlRawFor(port, cmd, cookiePath);
            if (raw == null) return null;
            var lines = new List<string>();
            bool inData = false;
            foreach (string line in raw)
            {
                if (inData)
                {
                    // Data-reply body (e.g. GETINFO ns/id/<fp>): lines arrive
                    // unprefixed until a lone "." terminator.
                    if (line == ".") { inData = false; continue; }
                    lines.Add(line);
                    continue;
                }
                if (line.StartsWith("250 ")) break;
                if (line.StartsWith("250-")) lines.Add(line.Substring(4));
                else if (line.StartsWith("250+")) { inData = true; lines.Add(line.Substring(4)); }
            }
            return lines;
        }

        // Returns the numeric status code of a control command ("250", "552", ...)
        // or -1 when the port is unreachable or auth fails.
        private static int ControlStatus(string cmd)
        {
            var raw = ControlRaw(cmd);
            if (raw == null) return -1;
            foreach (string line in raw)
            {
                int sp = line.IndexOf(' ');
                if (sp > 0)
                {
                    int code;
                    if (int.TryParse(line.Substring(0, sp), out code)) return code;
                }
            }
            return -1;
        }

        // Returns the value of a "KEY=value" token in a space-separated line.
        private static string Token(string line, string key)
        {
            string p = key + "=";
            foreach (string tok in line.Split(' '))
                if (tok.StartsWith(p)) return tok.Substring(p.Length);
            return null;
        }

        // Formats a byte count as B/KB/MB/GB for the set volume display.
        private static string FormatBytes(long b)
        {
            if (b < 1024) return b + " B";
            if (b < 1024L * 1024) return (b / 1024.0).ToString("0.#") + " KB";
            if (b < 1024L * 1024 * 1024) return (b / (1024.0 * 1024)).ToString("0.##") + " MB";
            return (b / (1024.0 * 1024 * 1024)).ToString("0.##") + " GB";
        }

        // Advertised bandwidth (bytes/s) of an exit, from GETINFO ns/id/<fp>.
        private static string ExitBandwidth(string fpHex)
        {
            try
            {
                fpHex = fpHex.TrimStart('$');
                if (fpHex == "?" || fpHex.Length != 40) return "?";
                var lines = ControlCommand("GETINFO ns/id/" + fpHex);
                if (lines == null) return "?";
                foreach (string raw in lines)
                {
                    string line = raw.Trim();
                    if (line.StartsWith("w "))
                    {
                        Match m = Regex.Match(line, "Bandwidth=(\\d+)");
                        if (m.Success) return m.Groups[1].Value;
                    }
                }
            }
            catch { }
            return "?";
        }

        // Reads the CONFLUX QUERY output, one entry per leg circuit. Every entry
        // is { set, circ, exit, legs, state, rttUs, streams, bytes }. Returns
        // null when the tor control port can't be reached.
        private static List<string[]> ConfluxQuery()
        {
            var lines = ControlCommand("CONFLUX QUERY");
            if (lines == null) return null;
            var legs = new List<string[]>();
            foreach (string raw in lines)
            {
                string line = raw.Trim();
                if (line.Length == 0) continue;
                if (line.StartsWith("CONFLUX status", StringComparison.OrdinalIgnoreCase)) continue;
                string set = Token(line, "SET");
                if (set == null) continue;
                string exit = Token(line, "EXIT");
                string state = Token(line, "STATE");
                int legsN = 0, rttUs = 0;
                long streams = 0, bytes = 0;
                int.TryParse(Token(line, "LEGS"), out legsN);
                int.TryParse(Token(line, "RTT_US"), out rttUs);
                long.TryParse(Token(line, "STREAMS"), out streams);
                long.TryParse(Token(line, "BYTES"), out bytes);
                legs.Add(new[] { set, Token(line, "CIRC") == null ? "?" : Token(line, "CIRC"),
                                 exit == null ? "?" : exit, legsN.ToString(),
                                 state == null ? "?" : state, rttUs.ToString(),
                                 streams.ToString(), bytes.ToString() });
            }
            return legs;
        }

        // Counts conflux sets/legs and returns the exit of the first set.
        private static string ConfluxInfo(out int sets, out int legs)
        {
            sets = 0;
            legs = 0;
            string exit = "?";
            var legList = ConfluxQuery();
            if (legList == null) return exit;
            var legCount = new Dictionary<string, int>();
            foreach (string[] leg in legList)
            {
                if (!legCount.ContainsKey(leg[0])) legCount[leg[0]] = 0;
                legCount[leg[0]]++;
                if (exit == "?" && leg[2] != "?" && leg[2] != null) exit = leg[2];
            }
            sets = legCount.Count;
            foreach (int n in legCount.Values) legs += n;
            return exit;
        }

        // Adds a new leg to a conflux set via the CONFLUX ADD control command
        // (TorJet extension). With no set id it targets the first set found, or
        // prompts when several sets exist.
        private static int AddConfluxLeg(string setId)
        {
            var legList = ConfluxQuery();
            if (legList == null)
            {
                Console.WriteLine("[x] cannot reach tor control port on 127.0.0.1:9051 (is tor running?).");
                return 1;
            }
            if (legList.Count == 0)
            {
                Console.WriteLine("[x] no conflux set to extend - conflux is NOT engaging (check consensus support).");
                return 1;
            }
            var sets = new Dictionary<string, List<string[]>>();
            foreach (string[] leg in legList)
            {
                if (!sets.ContainsKey(leg[0])) sets[leg[0]] = new List<string[]>();
                sets[leg[0]].Add(leg);
            }
            if (string.IsNullOrEmpty(setId))
            {
                if (sets.Count > 1)
                {
                    Console.WriteLine("  Multiple conflux sets; pick one:");
                    int i = 1;
                    foreach (var kv in sets)
                    {
                        Console.WriteLine("    " + i + ") " + kv.Key + " (" + kv.Value.Count + " legs)");
                        i++;
                    }
                    Console.Write("  Set number (Enter = 1): ");
                    string input;
                    try { input = Console.ReadLine(); }
                    catch { return 1; }
                    if (string.IsNullOrWhiteSpace(input))
                    {
                        foreach (var kv in sets) { setId = kv.Key; break; }
                    }
                    else
                    {
                        int n;
                        if (!int.TryParse(input.Trim(), out n) || n < 1 || n > sets.Count)
                        {
                            Console.WriteLine("    Invalid choice.");
                            return 1;
                        }
                        i = 1;
                        foreach (var kv in sets) { if (i == n) { setId = kv.Key; break; } i++; }
                    }
                }
                else
                {
                    foreach (var kv in sets) setId = kv.Key;
                }
            }
            if (!sets.ContainsKey(setId))
            {
                Console.WriteLine("[x] no conflux set \"" + setId + "\" - use a SET= id from CONFLUX QUERY.");
                return 1;
            }
            int status = ControlStatus("CONFLUX ADD " + setId);
            if (status == 250)
                Console.WriteLine("  Added a leg to conflux set " + setId + " - tor is building it.");
            else
                Console.WriteLine("[x] CONFLUX ADD " + setId + " failed (status " + status + ").");
            return status == 250 ? 0 : 1;
        }

        private static int ConfluxStatus(bool detailed)
        {
            var legList = ConfluxQuery();
            if (legList == null)
            {
                Console.WriteLine("[x] cannot reach tor control port on 127.0.0.1:9051 (is tor running?).");
                return 1;
            }
            bool debug = detailed || Environment.GetEnvironmentVariable("BENCH_DEBUG") == "1";
            Console.WriteLine();
            Console.WriteLine(Stamp() + "conflux status:");
            if (legList.Count == 0)
            {
                Console.WriteLine("  NO conflux circuits - conflux is NOT engaging (check consensus support).");
                return 1;
            }
            var sets = new Dictionary<string, List<string[]>>();
            foreach (string[] leg in legList)
            {
                if (!sets.ContainsKey(leg[0])) sets[leg[0]] = new List<string[]>();
                sets[leg[0]].Add(leg);
            }
            int legs = legList.Count;
            int linkedTotal = 0;
            foreach (string[] leg in legList)
                if (leg[4].Equals("LINKED", StringComparison.OrdinalIgnoreCase)) linkedTotal++;
            Console.WriteLine("  sets: " + sets.Count + "   legs: " + legs +
                              " (" + linkedTotal + " linked)" +
                              "   select: " + (confluxSelection >= 0 && confluxSelection < SetSelectionNames.Length ? SetSelectionNames[confluxSelection] : confluxSelection.ToString()) +
                              (confluxRttMax > 0 ? "   skip-slow: " + confluxRttMax + " ms" : "") +
                              (confluxRttPct > 0 ? "   top-%: " + confluxRttPct + "%" : ""));
            int idx = 1;
            foreach (var kv in sets)
            {
                int bestUs = int.MaxValue;
                string exit = "?";
                int linked = 0;
                long streams = 0, bytes = 0;
                foreach (string[] leg in kv.Value)
                {
                    long s, b;
                    if (long.TryParse(leg[6], out s) && s > streams) streams = s;
                    if (long.TryParse(leg[7], out b) && b > bytes) bytes = b;
                    if (leg[2] != "?") exit = leg[2];
                    if (leg[4].Equals("LINKED", StringComparison.OrdinalIgnoreCase))
                    {
                        linked++;
                        int rttUs;
                        if (int.TryParse(leg[5], out rttUs) && rttUs > 0 && rttUs < bestUs)
                            bestUs = rttUs;
                    }
                }
                string rtt = bestUs == int.MaxValue ? "?" : (bestUs / 1000) + " ms";
                Console.WriteLine("  set " + idx + ": " + kv.Value.Count + " legs (" + linked +
                                  " linked)  best " + rtt + "  exit " + exit +
                                  "  streams " + streams + "  " + FormatBytes(bytes));
                if (debug)
                {
                    foreach (string[] leg in kv.Value)
                    {
                        int rttUs;
                        string r = int.TryParse(leg[5], out rttUs) && rttUs > 0
                                       ? (rttUs / 1000) + " ms" : "?";
                        Console.WriteLine("      [leg] circ " + leg[1] + "  " + leg[4] +
                                          "  RTT " + r);
                    }
                    Console.WriteLine("      [bw] exit bandwidth: " + ExitBandwidth(exit) + " bytes/s");
                }
                idx++;
            }
            Log("conflux status: " + sets.Count + " set(s), " + legs +
                " leg(s), " + linkedTotal + " linked, select " +
                SetSelectionNames[confluxSelection] + ", skip " + confluxRttMax + "ms" +
                (confluxRttPct > 0 ? ", top " + confluxRttPct + "%" : ""));
            return 0;
        }

        // Background circuit health monitor. Every watchIntervalS seconds it
        // asks tor (CONFLUX QUERY) and closes the top watchRttPct% of linked
        // legs with the highest RTT across the WHOLE linked pool (a purely
        // relative, global weak-leg rule; the single best leg in the pool is
        // never closed and the pool is never fully pruned). tor then builds
        // replacement legs and conflux migrates any streams off the closed
        // ones. Non-conflux circuits are left alone. A watchCooldownS-second
        // gap between closes prevents circuit churn (relaxed during warmup).
        private static void CircuitWatchLoop()
        {
            DateTime lastClose = DateTime.MinValue;
            while (!circuitWatchStop)
            {
                Thread.Sleep(TimeSpan.FromSeconds(watchIntervalS));
                if (circuitWatchStop) break;
                if (torProc == null) continue;
                try { torProc.Refresh(); if (torProc.HasExited) break; }
                catch { break; }
                if (!circuitWatchWarmup &&
                    DateTime.UtcNow - lastClose < TimeSpan.FromSeconds(watchCooldownS)) continue;
                var legList = ConfluxQuery();
                if (legList == null) continue;

                // Forget per-circuit state for legs that no longer exist, so a
                // circuit id reused by tor never inherits stale strikes or
                // first-seen timestamps.
                var liveIds = new HashSet<string>();
                foreach (string[] leg in legList) liveIds.Add(leg[1]);
                var staleKeys = new List<string>();
                foreach (string k in weakStrikes.Keys) if (!liveIds.Contains(k)) staleKeys.Add(k);
                foreach (string k in staleKeys) weakStrikes.Remove(k);
                staleKeys.Clear();
                foreach (string k in unlinkedStrikes.Keys) if (!liveIds.Contains(k)) staleKeys.Add(k);
                foreach (string k in staleKeys) unlinkedStrikes.Remove(k);
                staleKeys.Clear();
                foreach (string k in unlinkedFirstSeen.Keys) if (!liveIds.Contains(k)) staleKeys.Add(k);
                foreach (string k in staleKeys) unlinkedFirstSeen.Remove(k);

                // Quality-based pruning (fully relative, global). The linked
                // legs with the highest RTT -- the top watchRttPct% of ALL
                // linked legs across every set -- are weak candidates, so a
                // slow single-leg set is pruned just like the weak legs of a
                // multi-leg set, with no absolute ms threshold. A leg must stay
                // weak for --watch-strikes consecutive passes before it is
                // closed. Legs stuck UNLINKED for --watch-unlinked-strikes
                // passes are closed as dead weight. The single best (lowest
                // RTT) leg in the whole pool is never a candidate.

                // Top up: sets with fewer legs than the configured target get
                // one CONFLUX ADD (capped per pass) so a set that never
                // reached ConfluxNumLegs or lost legs refills toward it. Only
                // the total leg count is used so we don't pile on while
                // replacement builds are still in flight.
                if (confluxLegs > 0)
                {
                    var setTotals = new Dictionary<string, int>();
                    foreach (string[] leg in legList)
                    {
                        int n;
                        if (!setTotals.TryGetValue(leg[0], out n)) n = 0;
                        setTotals[leg[0]] = n + 1;
                    }
                    int addedThisPass = 0;
                    foreach (var kv in setTotals)
                    {
                        if (addedThisPass >= watchMaxPerPass) break;
                        if (kv.Value >= confluxLegs) continue;
                        if (ControlStatus("CONFLUX ADD " + kv.Key) == 250)
                        {
                            addedThisPass++;
                            ClearProgressLine();
                            Log("monitor: added a leg to set " + kv.Key + " (" +
                                kv.Value + "/" + confluxLegs + " legs)");
                        }
                    }
                }

                // Pass 1: linked legs per set, and each set's list of linked
                // legs with a real RTT (used for the percentile ranking).
                var setLinked = new Dictionary<string, int>();
                var setLegs = new Dictionary<string, List<string[]>>();
                foreach (string[] leg in legList)
                {
                    if (!leg[4].Equals("LINKED", StringComparison.OrdinalIgnoreCase)) continue;
                    int ln;
                    if (!setLinked.TryGetValue(leg[0], out ln)) ln = 0;
                    setLinked[leg[0]] = ln + 1;
                    int rttUs;
                    if (!int.TryParse(leg[5], out rttUs) || rttUs <= 0) continue;
                    List<string[]> lst;
                    if (!setLegs.TryGetValue(leg[0], out lst)) { lst = new List<string[]>(); setLegs[leg[0]] = lst; }
                    lst.Add(new[] { leg[1], rttUs.ToString() });
                }

                // Pass 1.5: relative weak-leg rule. Across ALL linked legs of ALL
                // sets, the legs with the highest RTT -- the top watchRttPct% of
                // the whole linked pool -- are weak candidates (so a set with a
                // single slow leg is pruned just like the weak legs of a large
                // set; the comparison is global, not within each set). The count
                // is rounded up to at least one and capped at n-1, so the single
                // best (lowest RTT) leg in the pool is never a candidate and the
                // pool is never fully pruned. watchRttPct = 0 turns the rule off.
                var pctWeak = new HashSet<string>();
                if (watchRttPct > 0)
                {
                    var allRtts = new List<string[]>();
                    foreach (var kv in setLegs)
                        foreach (string[] leg in kv.Value)
                            allRtts.Add(new[] { leg[0], leg[1] }); // circ, rtt
                    int n = allRtts.Count;
                    if (n >= 2)
                    {
                        allRtts.Sort(delegate(string[] a, string[] b)
                        {
                            return int.Parse(b[1]) - int.Parse(a[1]);
                        });
                        int keep = (int)Math.Ceiling(n * watchRttPct / 100.0);
                        if (keep < 1) keep = 1;
                        if (keep > n - 1) keep = n - 1;
                        for (int i = 0; i < keep; i++)
                            pctWeak.Add(allRtts[i][0]);
                    }
                }

                // When weak-leg pruning is off (settings item 9 = 0), skip all
                // closures: the monitor still runs to keep strike state clean
                // and log the status, but no legs are touched.
                if (watchRttPct <= 0) continue;

                // Pass 2: classify every leg.
                var weak = new List<string[]>();
                var stuck = new List<string[]>();
                foreach (string[] leg in legList)
                {
                    string set = leg[0], circ = leg[1];
                    bool linked = leg[4].Equals("LINKED", StringComparison.OrdinalIgnoreCase);
                    int rttUs;
                    bool hasRtt = int.TryParse(leg[5], out rttUs) && rttUs > 0;

                    if (linked && hasRtt)
                    {
                        int strike = 0;
                        weakStrikes.TryGetValue(circ, out strike);
                        if (pctWeak.Contains(circ))
                        {
                            strike++;
                            weakStrikes[circ] = strike;
                            unlinkedStrikes.Remove(circ);
                            unlinkedFirstSeen.Remove(circ);
                            if (strike >= watchStrikes)
                                weak.Add(new[] { circ, rttUs.ToString(), set, "weak" });
                        }
                        else
                        {
                            weakStrikes.Remove(circ);
                            unlinkedStrikes.Remove(circ);
                            unlinkedFirstSeen.Remove(circ);
                        }
                    }
                    else if (!linked)
                    {
                        DateTime first;
                        if (!unlinkedFirstSeen.TryGetValue(circ, out first))
                        {
                            first = DateTime.UtcNow;
                            unlinkedFirstSeen[circ] = first;
                        }
                        int unStrike = 0;
                        unlinkedStrikes.TryGetValue(circ, out unStrike);
                        unStrike++;
                        unlinkedStrikes[circ] = unStrike;
                        // Never close young legs: right after a large launch
                        // burst they are still building, so killing them only
                        // adds churn and burns tor's per-set launch budget.
                        // Also skip stuck-unlinked pruning entirely while the
                        // tunnel is warming up (everything is building).
                        bool young = DateTime.UtcNow - first <
                                     TimeSpan.FromSeconds(watchUnlinkedGraceS);
                        if (!circuitWatchWarmup && !young &&
                            unStrike >= watchUnlinkedStrikes)
                            stuck.Add(new[] { circ, "0", set, "stuck-unlinked" });
                    }
                }
                if (weak.Count == 0 && stuck.Count == 0) continue;

                weak.Sort(delegate(string[] a, string[] b)
                {
                    return int.Parse(b[1]) - int.Parse(a[1]);
                });

                // Never close more than --watch-max-per-pass legs total in a
                // single pass so replacement builds don't pile up at once.
                // setLinked is decremented as legs are picked so each set loses
                // at most its flagged weak legs, even a sole leg.
                // setLinked was filled in Pass 1 above.
                var toRemove = new List<string[]>();
                var toRemoveReasons = new Dictionary<string, string>();
                foreach (string[] leg in weak)
                {
                    if (toRemove.Count >= watchMaxPerPass) break;
                    int n;
                    if (setLinked.TryGetValue(leg[2], out n) && n > 0)
                    {
                        setLinked[leg[2]] = n - 1;
                        toRemove.Add(leg);
                        toRemoveReasons[leg[0]] = leg[3];
                    }
                }
                foreach (string[] leg in stuck)
                {
                    if (toRemove.Count >= watchMaxPerPass) break;
                    toRemove.Add(leg);
                    toRemoveReasons[leg[0]] = leg[3];
                    unlinkedStrikes.Remove(leg[0]);
                }
                if (toRemove.Count == 0) continue;

                ClearProgressLine();
                int closed = 0;
                int closedWeak = 0, closedStuck = 0;
                string closedIds = "";
                foreach (string[] leg in toRemove)
                {
                    string reason;
                    toRemoveReasons.TryGetValue(leg[0], out reason);
                    if (ControlSend("CLOSECIRCUIT " + leg[0]))
                    {
                        closed++;
                        if (reason == "weak") closedWeak++; else closedStuck++;
                        weakStrikes.Remove(leg[0]);
                        if (closedIds.Length > 0) closedIds += ", ";
                        closedIds += leg[0];
                    }
                }
                if (closed > 0)
                {
                    lastClose = DateTime.UtcNow;
                    string what = "";
                    if (closedWeak > 0) what = closedWeak + " weak";
                    if (closedStuck > 0)
                        what = (what.Length > 0 ? what + ", " : "") + closedStuck + " stuck-unlinked";
                    Log("monitor: closed " + what + " leg(s) (" + closedIds +
                        ") - replacement building");
                    int cSets = 0, cLegs = 0, cLinked = 0;
                    var now = ConfluxQuery();
                    if (now != null)
                    {
                        var setIds = new HashSet<string>();
                        foreach (string[] leg in now)
                        {
                            setIds.Add(leg[0]);
                            if (leg[4].Equals("LINKED", StringComparison.OrdinalIgnoreCase)) cLinked++;
                        }
                        cSets = setIds.Count;
                        cLegs = now.Count;
                    }
                    lock (consoleLock)
                    {
                        Console.WriteLine();
                        Console.WriteLine(Stamp() + "leg cleanup report:");
                        Console.WriteLine("  closed    : " + closed + " (" + what + ")");
                        Console.WriteLine("  circuits  : " + closedIds);
                        Console.WriteLine("  conflux   : " + cSets + " set(s), " + cLegs +
                                          " leg(s), " + cLinked + " linked");
                        Console.WriteLine("  next scan : every " + watchIntervalS + " s; next close " +
                                          "no earlier than " + watchCooldownS + " s from now");
                    }
                }
            }
        }

        // Returns tor's own bootstrap status. Two sources are used and the more
        // advanced one wins:
        //   - the control port (GETINFO status/bootstrap-phase) is authoritative;
        //   - the log fallback ("Bootstrapped NN% (tag)") covers the window
        //     before the control port answers and guards against the launcher
        //     missing the 100% line because it scrolled out of the log tail.
        // tor.log is deleted before every start, so a stale "100%" from an older
        // run can never be misread as the current run's status.
        // Returns false when neither source has a percentage yet.
        private static bool BootstrapPhase(out int pct, out string tag, out string summary)
        {
            return BootstrapPhaseFor(9051, TorLog, ControlCookie, out pct, out tag, out summary);
        }

        private static bool BootstrapPhaseFor(int controlPort, string logPath, string cookiePath,
                                              out int pct, out string tag, out string summary)
        {
            pct = -1;
            tag = "";
            summary = "";
            int ctl = -1, log = -1;
            string ctlTag = "", logTag = "", ctlSummary = "";

            var lines = ControlCommandFor(controlPort, "GETINFO status/bootstrap-phase", cookiePath);
            if (lines != null)
            {
                foreach (string raw in lines)
                {
                    string l = raw.Trim();
                    if (l.Length == 0) continue;
                    Match m = Regex.Match(l, @"PROGRESS=(\d+)");
                    if (m.Success)
                    {
                        ctl = int.Parse(m.Groups[1].Value);
                        Match t = Regex.Match(l, @"TAG=([^\s]+)");
                        if (t.Success) ctlTag = t.Groups[1].Value;
                        Match s = Regex.Match(l, @"SUMMARY=(.*)$");
                        if (s.Success) ctlSummary = s.Groups[1].Value.Trim('"');
                        break;
                    }
                }
            }

            string tail = string.Join("\n", ReadLogTailFile(logPath, 8192));
            MatchCollection ms = Regex.Matches(tail, @"Bootstrapped\s+(\d+)%\s*(?:\(([^)]+)\))?");
            if (ms.Count > 0)
            {
                Match m = ms[ms.Count - 1];
                log = int.Parse(m.Groups[1].Value);
                if (m.Groups[2].Success) logTag = m.Groups[2].Value;
            }

            if (log > ctl)
            {
                pct = log;
                tag = logTag;
                return true;
            }
            if (ctl >= 0)
            {
                pct = ctl;
                tag = ctlTag;
                summary = ctlSummary;
                return true;
            }
            return false;
        }

        // Redraws the bootstrap progress bar on the current console line.
        // The percentage is snapped to 10% steps (0, 10, 20, ..., 100).
        private static void DrawProgress(int pct, string label)
        {
            lock (consoleLock)
            {
                const int width = 24;
                pct = (pct / 10) * 10;
                if (pct > 100) pct = 100;
                if (pct < 0) pct = 0;
                int filled = (int)Math.Round(pct / 100.0 * width);
                if (filled > width) filled = width;
                if (filled < 0) filled = 0;
                string bar = new string('#', filled) + new string('.', width - filled);
                string line = "    [" + bar + "] " + pct.ToString() + "%";
                if (!string.IsNullOrEmpty(label)) line += "  " + label;
                if (line.Length < progressLineLen) line = line.PadRight(progressLineLen);
                Console.Write("\r" + line);
                progressLineLen = line.Length;
            }
        }

        private static void ClearProgressLine()
        {
            lock (consoleLock)
            {
                if (progressLineLen > 0)
                {
                    Console.Write("\r" + new string(' ', progressLineLen) + "\r");
                    progressLineLen = 0;
                }
            }
        }

        // Local clock stamp used on launcher log lines, e.g. "[12:34:56] ".
        private static string Stamp()
        {
            return "[" + DateTime.Now.ToString("HH:mm:ss") + "] ";
        }

        // Appends a timestamped line to the launcher log (data\jet.log). All the
        // operational detail (monitor actions, keep-alive, status snapshots) goes here
        // so the live console stays clean. Logging never blocks or fails the app.
        private static void Log(string msg)
        {
            try
            {
                using (FileStream fs = new FileStream(JetLog, FileMode.Append, FileAccess.Write,
                                                      FileShare.ReadWrite))
                using (StreamWriter sw = new StreamWriter(fs, Encoding.UTF8))
                    sw.WriteLine(Stamp() + msg);
            }
            catch { }
        }

        // Reads the tail of a log file into lines without fighting the writer for
        // the lock (FileShare.ReadWrite). Used by ViewLog so tor.log can be shown
        // while tor.exe still has it open.
        private static string[] ReadLogTailFile(string path, int bytes)
        {
            try
            {
                using (FileStream fs = new FileStream(path, FileMode.Open, FileAccess.Read,
                                                      FileShare.ReadWrite))
                {
                    long start = Math.Max(0, fs.Length - bytes);
                    fs.Seek(start, SeekOrigin.Begin);
                    using (StreamReader sr = new StreamReader(fs, Encoding.UTF8, true))
                        return sr.ReadToEnd().Split(new[] { '\r', '\n' },
                                                    StringSplitOptions.RemoveEmptyEntries);
                }
            }
            catch { return new string[0]; }
        }

        // Shows the tail of tor.log. tor writes every line with its own exact
        // timestamp (e.g. "Aug 12 12:34:56.789 [notice] ..."), which is kept
        // as-is; lines without one get a local clock stamp added.
        private static void ViewLog()
        {
            const int maxLines = 40;
            lock (consoleLock)
            {
                ClearProgressLine();
                string[] jet = ReadLogTailFile(JetLog, 8192);
                Console.WriteLine(Stamp() + "launcher log - last " +
                                  Math.Min(jet.Length, maxLines) + " of " +
                                  jet.Length + " line(s):");
                if (jet.Length == 0) Console.WriteLine("  (no launcher events yet)");
                for (int i = Math.Max(0, jet.Length - maxLines); i < jet.Length; i++)
                    Console.WriteLine("  " + jet[i]);
                Console.WriteLine();
                string[] tor = ReadLogTailFile(TorLog, 16384);
                Console.WriteLine(Stamp() + "tor log - last " +
                                  Math.Min(tor.Length, maxLines) + " of " +
                                  tor.Length + " line(s):");
                if (tor.Length == 0) Console.WriteLine("  (empty - tor has not logged yet)");
                for (int i = Math.Max(0, tor.Length - maxLines); i < tor.Length; i++)
                    Console.WriteLine("  " + tor[i]);
            }
        }

        // Starts tor for the given mode, writes torrc, stops any previous run,
        // and waits until bootstrap reaches 100%. Returns the process or null.
        // `aborted` is set when the user pressed C to stop during bootstrap.
        // interactive=false (GUI) skips all console drawing; progress is
        // reported through the callback instead (pct, tag).
        private static Process StartTorAndWait(int mode, int strategy,
                                               bool interactive, Action<int, string> progress,
                                               out string errorMessage, out bool aborted)
        {
            errorMessage = null;
            aborted = false;
            if (!File.Exists(TorExe))
            {
                errorMessage = "tor.exe not found in " + DataDir;
                return null;
            }
            StopPreviousRun();
            // The OS releases listening sockets only after the killed process
            // has fully exited, which lags Kill(). Wait until our ports are
            // free and drop the stale lock file so a fresh start never races
            // the teardown and dies with "Address already in use".
            for (int i = 0; i < 30 && PreviousRunActive(); i++) Thread.Sleep(500);
            try { if (File.Exists(LockFile)) File.Delete(LockFile); } catch { }
            if (!WriteTorrc(mode, strategy))
            {
                errorMessage = "failed to write torrc (bridge file missing?).";
                return null;
            }
            Directory.CreateDirectory(Path.Combine(DataDir, "data"));
            try { if (File.Exists(TorLog)) File.Delete(TorLog); } catch { }

            ProcessStartInfo psi = new ProcessStartInfo
            {
                FileName = TorExe,
                Arguments = "-f \"torrc\"",
                WorkingDirectory = DataDir,
                UseShellExecute = false,
                CreateNoWindow = true,
                RedirectStandardError = true
            };

            // If tor dies in the first few seconds because a leftover lock or
            // occupied port was still held from the previous run, wait and
            // retry with a fresh lock file before giving up. tor writes its
            // file log only AFTER all listeners bound, so early bind failures
            // appear solely on stderr - captured below.
            StringBuilder errBuf = new StringBuilder();
            for (int attempt = 1; ; attempt++)
            {
                Process proc;
                try { proc = Process.Start(psi); }
                catch (Exception ex)
                {
                    errorMessage = "failed to start tor: " + ex.Message;
                    return null;
                }
                lock (errBuf) errBuf.Length = 0;
                try
                {
                    proc.ErrorDataReceived += delegate(object s, DataReceivedEventArgs e)
                    {
                        if (e.Data != null)
                            lock (errBuf) errBuf.AppendLine(e.Data);
                    };
                    proc.BeginErrorReadLine();
                }
                catch { }
                torProc = proc;
                Console.WriteLine("tor started (PID " + proc.Id + "), bootstrapping...");

                DateTime started = DateTime.UtcNow;
                DateTime deadline = started.AddMinutes(10);
                int lastPct = -1;
                string lastTag = "";
                DateTime stuckSince = DateTime.UtcNow;
                bool retry = false;
                while (DateTime.UtcNow < deadline)
                {
                    try { proc.Refresh(); } catch { }
                    if (proc.HasExited)
                    {
                        ClearProgressLine();
                        Thread.Sleep(300);   // let async stderr drain
                        string tail;
                        lock (errBuf) tail = errBuf.ToString();
                        if (tail.Length == 0) tail = ReadLogTail(1500);
                        if (attempt < 3 &&
                            DateTime.UtcNow - started < TimeSpan.FromSeconds(45))
                        {
                            if (tail.IndexOf("already in use", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                tail.IndexOf("lock file", StringComparison.OrdinalIgnoreCase) >= 0)
                            {
                                Console.WriteLine("tor exited early (code " + proc.ExitCode +
                                                  ") - previous run still releasing ports, retrying...");
                                retry = true;
                                break;
                            }
                        }
                        errorMessage = "tor exited with code " + proc.ExitCode + ".\n" + tail;
                        return null;
                    }
                    try
                    {
                        if (interactive && Console.KeyAvailable &&
                            Console.ReadKey(true).Key == ConsoleKey.C)
                        {
                            ClearProgressLine();
                            try { proc.Kill(); } catch { }
                            aborted = true;
                            return null;
                        }
                    }
                    catch { }
                    int pct;
                    string tag;
                    string summary;
                    if (BootstrapPhase(out pct, out tag, out summary))
                    {
                        if (pct >= 100)
                        {
                            if (interactive)
                            {
                                DrawProgress(100, tag);
                                Console.WriteLine();
                                progressLineLen = 0;
                            }
                            else if (progress != null) progress(100, tag);
                            return proc;
                        }
                        if (pct != lastPct)
                        {
                            lastPct = pct;
                            lastTag = tag;
                            stuckSince = DateTime.UtcNow;
                            if (interactive) DrawProgress(pct, tag);
                            else if (progress != null) progress(pct, tag);
                        }
                        else if (DateTime.UtcNow - stuckSince > TimeSpan.FromMinutes(3))
                        {
                            if (interactive) DrawProgress(pct, tag + "  (still waiting...)");
                        }
                        else
                        {
                            if (interactive) DrawProgress(pct, tag);
                        }
                    }
                    Thread.Sleep(1500);
                }
                if (retry)
                {
                    for (int i = 0; i < 30 && PreviousRunActive(); i++)
                        Thread.Sleep(500);
                    try { if (File.Exists(LockFile)) File.Delete(LockFile); } catch { }
                    continue;
                }
                if (interactive) ClearProgressLine();
                if (!proc.HasExited)
                {
                    errorMessage = "bootstrap did not reach 100% in 10 minutes (last seen: " +
                                   lastPct + "% " + lastTag + ").\n" + ReadLogTail(1500);
                    return null;
                }
                errorMessage = "tor exited with code " + proc.ExitCode + ".\n" + ReadLogTail(1500);
                return null;
            }
        }

        private static string benchUrl;
        private static readonly string[] BenchEndpoints =
        {
            "https://speed.cloudflare.com/__down?bytes=10485760",
            "https://speed.hetzner.de/10MB.bin",
            "http://speedtest.tele2.net/10MB.zip"
        };

        // Lightweight endpoints that answer 204 No Content - perfect for the
        // keep-alive pings. They are fetched with a plain HTTP GET through a
        // real SOCKS5 CONNECT on the dedicated keep-alive port 127.0.0.1:9052,
        // i.e. the same tor instance the user tests, so a healthy report is not
        // a false positive. The port is configured with NoIsolateSOCKSAuth, so
        // the marker username below does not push the pings onto their own
        // circuits; tor recognizes the username and routes each ping to the
        // least-loaded conflux set regardless of the configured selection
        // policy and RTT filters, keeping the pings spread evenly across all
        // sets.
        private class PingTarget
        {
            public string Host;
            public string Path;
            public PingTarget(string host, string path) { Host = host; Path = path; }
        }
        private static readonly PingTarget[] PingTargets =
        {
            new PingTarget("connectivitycheck.gstatic.com", "/generate_204"),
            new PingTarget("cp.cloudflare.com", "/generate_204"),
            new PingTarget("www.msftconnecttest.com", "/connecttest.txt")
        };

        private static bool IsTimeoutException(Exception ex)
        {
            while (ex != null)
            {
                SocketException se = ex as SocketException;
                if (se != null && se.SocketErrorCode == SocketError.TimedOut) return true;
                ex = ex.InnerException;
            }
            return false;
        }

        // Reads exactly `n` bytes; false on short read or timeout.
        private static bool ReadExact(NetworkStream ns, byte[] buf, int n)
        {
            int got = 0;
            while (got < n)
            {
                int r = ns.Read(buf, got, n - got);
                if (r <= 0) return false;
                got += r;
            }
            return true;
        }

        // Reads the HTTP response head (status line + headers) up to CRLFCRLF.
        private static string ReadHttpHead(NetworkStream ns)
        {
            StringBuilder sb = new StringBuilder();
            byte[] one = new byte[1];
            while (sb.Length < 8192)
            {
                int r = ns.Read(one, 0, 1);
                if (r <= 0) break;
                sb.Append((char)one[0]);
                int len = sb.Length;
                if (len >= 4 && sb[len - 4] == '\r' && sb[len - 3] == '\n' &&
                    sb[len - 2] == '\r' && sb[len - 1] == '\n')
                    break;
            }
            return sb.ToString();
        }

        // One real tunnel probe end to end: TCP connect to tor's dedicated
        // keep-alive SOCKS port (127.0.0.1:9052), SOCKS5 username/password auth
        // with the marker username, SOCKS5 CONNECT to the target, then a plain
        // HTTP GET through the tunnel. Returns 1 = ok (2xx), 0 = failed,
        // -1 = timed out; `elapsedMs` carries the real round-trip delay of the
        // successful ping.
        private static int PingSocks(string host, string path, out long elapsedMs)
        {
            elapsedMs = 0;
            Stopwatch sw = Stopwatch.StartNew();
            TcpClient tc = null;
            NetworkStream ns = null;
            try
            {
                tc = new TcpClient();
                IAsyncResult ar = tc.BeginConnect(IPAddress.Loopback, KeepAliveSocksPort, null, null);
                if (!ar.AsyncWaitHandle.WaitOne(4000))
                {
                    tc.Close();
                    return -1;
                }
                tc.EndConnect(ar);
                tc.ReceiveTimeout = 5000;
                tc.SendTimeout = 5000;
                ns = tc.GetStream();
                ns.ReadTimeout = 5000;
                ns.WriteTimeout = 5000;

                // Only offer username/password auth (0x02). The tor side of
                // 9052 is NoIsolateSOCKSAuth but still accepts it; the username
                // marks the stream as a keep-alive ping for conflux set spread.
                byte[] greet = { 0x05, 0x01, 0x02 };
                ns.Write(greet, 0, 3);
                byte[] ga = new byte[2];
                if (!ReadExact(ns, ga, 2)) return 0;
                if (ga[0] != 0x05 || ga[1] != 0x02) return 0;

                byte[] userB = Encoding.ASCII.GetBytes(KeepAliveUsername);
                byte[] passB = Encoding.ASCII.GetBytes("torjet");
                byte[] auth = new byte[1 + 1 + userB.Length + 1 + passB.Length];
                auth[0] = 0x01;
                auth[1] = (byte)userB.Length;
                Buffer.BlockCopy(userB, 0, auth, 2, userB.Length);
                auth[2 + userB.Length] = (byte)passB.Length;
                Buffer.BlockCopy(passB, 0, auth, 3 + userB.Length, passB.Length);
                ns.Write(auth, 0, auth.Length);
                byte[] ar2 = new byte[2];
                if (!ReadExact(ns, ar2, 2)) return 0;
                if (ar2[0] != 0x01 || ar2[1] != 0x00) return 0;

                byte[] hostB = Encoding.ASCII.GetBytes(host);
                byte[] cmd = new byte[5 + hostB.Length + 2];
                cmd[0] = 0x05; cmd[1] = 0x01; cmd[2] = 0x00; cmd[3] = 0x03;
                cmd[4] = (byte)hostB.Length;
                Buffer.BlockCopy(hostB, 0, cmd, 5, hostB.Length);
                cmd[cmd.Length - 2] = 0x00;
                cmd[cmd.Length - 1] = 0x50;
                ns.Write(cmd, 0, cmd.Length);

                byte[] repHdr = new byte[4];
                if (!ReadExact(ns, repHdr, 4)) return 0;
                if (repHdr[0] != 0x05 || repHdr[1] != 0x00) return 0;
                int rest;
                if (repHdr[3] == 0x01) rest = 6;
                else if (repHdr[3] == 0x03)
                {
                    int dl = ns.ReadByte();
                    if (dl < 0) return 0;
                    rest = 1 + dl + 2;
                }
                else if (repHdr[3] == 0x04) rest = 18;
                else return 0;
                byte[] tail = new byte[rest];
                if (!ReadExact(ns, tail, rest)) return 0;

                string req = "GET " + path + " HTTP/1.1\r\n" +
                             "Host: " + host + "\r\n" +
                             "User-Agent: torjet-warmup/1.0\r\n" +
                             "Connection: close\r\n\r\n";
                byte[] reqB = Encoding.ASCII.GetBytes(req);
                ns.Write(reqB, 0, reqB.Length);

                string head = ReadHttpHead(ns);
                sw.Stop();
                elapsedMs = sw.ElapsedMilliseconds;
                if (head.Length == 0) return 0;
                int sp = head.IndexOf(' ');
                if (sp < 0 || head.Length < sp + 4) return 0;
                int code;
                if (!int.TryParse(head.Substring(sp + 1, 3), out code)) return 0;
                return (code >= 200 && code < 300) ? 1 : 0;
            }
            catch (Exception ex)
            {
                sw.Stop();
                return IsTimeoutException(ex) ? -1 : 0;
            }
            finally
            {
                if (ns != null) try { ns.Close(); } catch { }
                if (tc != null) try { tc.Close(); } catch { }
            }
        }

        // Permanent keep-alive through the real SOCKS proxy
        // (dedicated keep-alive port 127.0.0.1:9052):
        // one generate_204 request dispatched every second for as long as the
        // session runs. Each request is allowed up to 5 s to get a response and
        // is recorded as ok / fail / timeout. Requests overlap, so a slow one
        // never stalls the 1/s cadence. The keep-alive keeps the tunnel warm and
        // honest: if tor dies, the pings start failing. It runs in the
        // background while the menu is served and stops only when the session is
        // torn down (C, tor exit or Ctrl+C).
        private static readonly object keepAliveLock = new object();
        private static volatile bool keepAliveStop;
        private static volatile bool keepAliveStarted;
        private static volatile int keepAliveDone, keepAliveOk, keepAliveFail, keepAliveTimeouts;
        private static long keepAliveTotalMs, keepAliveBestMs, keepAliveWorstMs;
        private static Thread keepAliveThread;
        private static bool keepAliveEnabled = ReadKeepAliveSetting();

        private static void KeepAliveLoop()
        {
            Stopwatch clock = Stopwatch.StartNew();
            long tick = 0;
            while (!keepAliveStop)
            {
                tick++;
                PingTarget target = PingTargets[(int)((tick - 1) % PingTargets.Length)];
                long ems;
                int r = PingSocks(target.Host, target.Path, out ems);
                lock (keepAliveLock)
                {
                    keepAliveDone++;
                    if (r == 1)
                    {
                        if (ems < 0) ems = 0;
                        keepAliveOk++;
                        keepAliveTotalMs += ems;
                        if (ems < keepAliveBestMs) keepAliveBestMs = ems;
                        if (ems > keepAliveWorstMs) keepAliveWorstMs = ems;
                    }
                    else if (r == -1) keepAliveTimeouts++;
                    else keepAliveFail++;
                }
                long targetMs = tick * 1000;
                while (!keepAliveStop && clock.ElapsedMilliseconds < targetMs)
                    Thread.Sleep(50);
            }
        }

        private static void StartKeepAlive()
        {
            lock (keepAliveLock)
            {
                keepAliveStop = false;
                keepAliveStarted = true;
                keepAliveDone = 0;
                keepAliveOk = 0;
                keepAliveFail = 0;
                keepAliveTimeouts = 0;
                keepAliveTotalMs = 0;
                keepAliveBestMs = long.MaxValue;
                keepAliveWorstMs = 0;
            }
            keepAliveThread = new Thread(KeepAliveLoop) { IsBackground = true };
            keepAliveThread.Start();
            Log("keep-alive: started - 1 request/s via SOCKS 127.0.0.1:9052, 5 s timeout");
        }

        private static void StopKeepAlive()
        {
            if (!keepAliveStarted) return;
            keepAliveStarted = false;
            keepAliveStop = true;
            if (keepAliveThread != null)
            {
                try { keepAliveThread.Join(2000); } catch { }
                keepAliveThread = null;
            }
            lock (keepAliveLock)
            {
                double avg = keepAliveOk > 0 ? (double)keepAliveTotalMs / keepAliveOk : 0;
                Log("keep-alive: stopped - " + keepAliveOk + " ok / " + keepAliveFail +
                    " fail / " + keepAliveTimeouts + " timeouts, avg " +
                    Math.Round(avg) + " ms");
            }
        }

        private static void ShowKeepAliveReport()
        {
            lock (keepAliveLock)
            {
                Console.WriteLine();
                Console.WriteLine("  --- keep-alive report ---");
                if (!keepAliveStarted)
                {
                    Console.WriteLine("  keep-alive is OFF (toggle with J, or enable in Settings)");
                    Console.WriteLine();
                    return;
                }
                double avg = keepAliveOk > 0 ? (double)keepAliveTotalMs / keepAliveOk : 0;
                Console.WriteLine("  sent     : " + keepAliveDone);
                Console.WriteLine("  ok       : " + keepAliveOk);
                Console.WriteLine("  fail     : " + keepAliveFail);
                Console.WriteLine("  timeouts : " + keepAliveTimeouts);
                Console.WriteLine("  RTT      : avg " + Math.Round(avg) + " ms, best " +
                                  (keepAliveBestMs == long.MaxValue ? "-" : keepAliveBestMs.ToString()) +
                                  " ms, worst " + keepAliveWorstMs + " ms");
                Console.WriteLine();
            }
        }

        private static void ToggleKeepAlive()
        {
            if (keepAliveStarted)
            {
                StopKeepAlive();
                keepAliveEnabled = false;
                WriteKeepAliveFile(false);
                Console.WriteLine("  keep-alive OFF");
            }
            else
            {
                keepAliveEnabled = true;
                WriteKeepAliveFile(true);
                StartKeepAlive();
                Console.WriteLine("  keep-alive ON (1 request/s)");
            }
        }

        // --- DNS cache for TUN mode ------------------------------------------
        // While TUN routes all traffic through tor, system DNS points at
        // 127.0.0.1:53. This tiny stub answers from an in-memory TTL cache and
        // otherwise forwards the raw UDP datagram to tor's DNSPort
        // (127.0.0.1:53530), cutting the full-circuit latency of repeated
        // lookups. Started when TUN comes up, stopped on TUN off / cleanup.
        private const int DnsCachePort = 53;
        private const int DnsUpstreamPort = 53530;
        private const int DnsCacheMaxEntries = 4096;
        private static volatile bool dnsCacheStop;
        private static Thread dnsCacheThread;
        private static UdpClient dnsListener;
        private static readonly object dnsLock = new object();

        private sealed class DnsEntry { public byte[] Reply; public DateTime Expires; }
        private static readonly Dictionary<string, DnsEntry> dnsCache =
            new Dictionary<string, DnsEntry>(StringComparer.Ordinal);

        // Key for the question section: lowercased qname + qtype (transaction
        // ID excluded - it is rewritten per reply).
        private static string DnsQuestionKey(byte[] q, int len)
        {
            try
            {
                if (len < 13) return null;
                int idx = 12;
                var sb = new StringBuilder();
                while (idx < len && q[idx] != 0)
                {
                    int l = q[idx];
                    if ((l & 0xC0) != 0 || idx + 1 + l > len) return null;
                    sb.Append(Encoding.ASCII.GetString(q, idx + 1, l).ToLowerInvariant());
                    sb.Append('.');
                    idx += l + 1;
                }
                if (idx + 5 > len) return null;
                int qtype = (q[idx + 1] << 8) | q[idx + 2];
                return sb.ToString() + "|" + qtype;
            }
            catch { return null; }
        }

        // Skips a (possibly compressed) DNS name; returns index after it.
        private static int DnsSkipName(byte[] r, int idx, int len)
        {
            while (idx < len)
            {
                int l = r[idx];
                if (l == 0) return idx + 1;
                if ((l & 0xC0) == 0xC0) return idx + 2;
                idx += l + 1;
            }
            return idx;
        }

        // Smallest TTL across all answer records, or -1 when unparsable.
        private static int DnsMinTtl(byte[] r, int len)
        {
            try
            {
                if (len < 12) return -1;
                int qd = (r[4] << 8) | r[5];
                int an = (r[6] << 8) | r[7];
                int idx = 12;
                for (int i = 0; i < qd && idx < len; i++)
                {
                    idx = DnsSkipName(r, idx, len);
                    idx += 4;
                }
                int best = -1;
                for (int i = 0; i < an && idx + 10 <= len; i++)
                {
                    idx = DnsSkipName(r, idx, len);
                    if (idx + 10 > len) break;
                    int ttl = (r[idx + 4] << 24) | (r[idx + 5] << 16) |
                              (r[idx + 6] << 8) | r[idx + 7];
                    if (ttl < 0) ttl = 0;
                    if (best < 0 || ttl < best) best = ttl;
                    int rdlen = (r[idx + 8] << 8) | r[idx + 9];
                    idx += 10 + rdlen;
                }
                return best;
            }
            catch { return -1; }
        }

        private static void DnsCacheLoop()
        {
            UdpClient listener = null;
            try { listener = new UdpClient(new IPEndPoint(IPAddress.Loopback, DnsCachePort)); }
            catch (Exception ex)
            {
                Log("dns-cache: cannot bind 127.0.0.1:" + DnsCachePort +
                    " (" + ex.Message + ") - DNS will bypass the cache.");
                lock (dnsLock) { dnsCacheThread = null; }
                return;
            }
            lock (dnsLock)
            {
                if (dnsCacheStop) { try { listener.Close(); } catch { } return; }
                dnsListener = listener;
            }
            Log("dns-cache: listening on 127.0.0.1:" + DnsCachePort +
                " -> tor 127.0.0.1:" + DnsUpstreamPort);
            while (!dnsCacheStop)
            {
                IPEndPoint from = new IPEndPoint(IPAddress.Loopback, 0);
                byte[] query;
                try { query = listener.Receive(ref from); }
                catch { break; } // closed by Stop()
                ThreadPool.QueueUserWorkItem(delegate(object o)
                {
                    object[] a = (object[])o;
                    HandleDnsQuery(listener, (byte[])a[0], (IPEndPoint)a[1]);
                }, new object[] { query, from });
            }
            lock (dnsLock) { if (dnsListener == listener) dnsListener = null; }
            try { listener.Close(); } catch { }
        }

        private static void HandleDnsQuery(UdpClient listener, byte[] query, IPEndPoint from)
        {
            try
            {
                string key = DnsQuestionKey(query, query.Length);
                DnsEntry hit = null;
                if (key != null)
                    lock (dnsLock)
                    {
                        DnsEntry e;
                        if (dnsCache.TryGetValue(key, out e))
                        {
                            if (e.Expires > DateTime.UtcNow) hit = e;
                            else dnsCache.Remove(key);
                        }
                    }
                if (hit != null)
                {
                    byte[] reply = new byte[hit.Reply.Length];   // patch in THIS query's ID
                    Buffer.BlockCopy(hit.Reply, 0, reply, 0, reply.Length);
                    reply[0] = query[0];
                    reply[1] = query[1];
                    listener.Send(reply, reply.Length, from);
                    Interlocked.Increment(ref dnsCacheHits);
                    return;
                }
                using (UdpClient up = new UdpClient())
                {
                    up.Client.ReceiveTimeout = 5000;
                    up.Connect(IPAddress.Loopback, DnsUpstreamPort);
                    up.Send(query, query.Length);
                    IPEndPoint any = new IPEndPoint(IPAddress.Any, 0);
                    byte[] resp = up.Receive(ref any);
                    listener.Send(resp, resp.Length, from);
                    // Cache only successful answers with a parsable positive TTL.
                    if (key != null && resp.Length > 3 && (resp[3] & 0x0F) == 0)
                    {
                        int ttl = DnsMinTtl(resp, resp.Length);
                        if (ttl > 0)
                        {
                            if (ttl < 10) ttl = 10;
                            if (ttl > 3600) ttl = 3600;
                            lock (dnsLock)
                            {
                                if (dnsCache.Count >= DnsCacheMaxEntries) dnsCache.Clear();
                                dnsCache[key] = new DnsEntry
                                {
                                    Reply = resp,
                                    Expires = DateTime.UtcNow.AddSeconds(ttl)
                                };
                            }
                        }
                    }
                }
            }
            catch { }
        }

        private static long dnsCacheHits;

        private static void DnsCacheStart()
        {
            lock (dnsLock)
            {
                if (dnsCacheThread != null) return;
                dnsCacheStop = false;
                dnsCacheThread = new Thread(DnsCacheLoop) { IsBackground = true };
                dnsCacheThread.Start();
            }
        }

        private static void DnsCacheStop()
        {
            Thread t;
            lock (dnsLock)
            {
                t = dnsCacheThread;
                dnsCacheThread = null;
                dnsCacheStop = true;
                if (dnsListener != null)
                {
                    try { dnsListener.Close(); } catch { }
                    dnsListener = null;
                }
            }
            if (t != null) { try { t.Join(2000); } catch { } }
        }

        // Picks the first speed endpoint reachable through the proxy.
        private static void ProbeBenchUrl()
        {
            foreach (string u in BenchEndpoints)
            {
                try
                {
                    HttpWebRequest req = (HttpWebRequest)WebRequest.Create(u);
                    req.Proxy = new WebProxy("127.0.0.1", 8118);
                    req.Method = "GET";
                    req.Timeout = 30000;
                    req.ReadWriteTimeout = 30000;
                    req.UserAgent = "torjet-speedtest/1.0";
                    using (WebResponse resp = req.GetResponse())
                    using (Stream s = resp.GetResponseStream())
                    {
                        byte[] buf = new byte[16384];
                        if (s.Read(buf, 0, buf.Length) > 0)
                        {
                            benchUrl = u;
                            Console.WriteLine("speed endpoint OK: " + u);
                            return;
                        }
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine("endpoint failed (" + u + "): " + ex.Message);
                }
            }
            benchUrl = null;
            Console.WriteLine("[!] no speed endpoint reachable through the proxy.");
        }

        // Downloads `bytesPerStream` through the proxy on `streams` parallel
        // connections and reports aggregate throughput + peak sampled rate.
        private static void BenchDownload(int streams, long bytesPerStream,
                                          out long total, out double secs, out double peak)
        {
            long totalBytes = 0;
            long lastBytes = 0;
            double lastElapsed = 0;
            double peakRate = 0;
            var errors = new List<string>();
            Stopwatch sw = new Stopwatch();
            sw.Start();
            var threads = new List<Thread>();
            for (int i = 0; i < streams; i++)
            {
                Thread th = new Thread(delegate()
                {
                    long got = 0;
                    try
                    {
                        HttpWebRequest req = (HttpWebRequest)WebRequest.Create(
                            benchUrl ?? BenchEndpoints[0]);
                        req.Proxy = new WebProxy("127.0.0.1", 8118);
                        req.Method = "GET";
                        req.Timeout = 180000;
                        req.ReadWriteTimeout = 180000;
                        req.UserAgent = "torjet-speedtest/1.0";
                        using (WebResponse resp = req.GetResponse())
                        using (Stream s = resp.GetResponseStream())
                        {
                            byte[] buf = new byte[64 * 1024];
                            int n;
                            while ((n = s.Read(buf, 0, buf.Length)) > 0) got += n;
                        }
                    }
                    catch (Exception ex)
                    {
                        lock (errors) errors.Add(ex.Message);
                    }
                    Interlocked.Add(ref totalBytes, got);
                });
                th.IsBackground = true;
                threads.Add(th);
                th.Start();
            }
            while (true)
            {
                bool alive = false;
                foreach (Thread th in threads) if (th.IsAlive) { alive = true; break; }
                if (!alive) break;
                Thread.Sleep(200);
                double el = sw.Elapsed.TotalSeconds;
                long tb = Interlocked.Read(ref totalBytes);
                double dt = el - lastElapsed;
                if (dt >= 1.0)
                {
                    double rate = (tb - lastBytes) / dt;
                    if (rate > peakRate) peakRate = rate;
                    lastBytes = tb;
                    lastElapsed = el;
                }
            }
            sw.Stop();
            total = Interlocked.Read(ref totalBytes);
            secs = sw.Elapsed.TotalSeconds;
            double finalDt = secs - lastElapsed;
            if (finalDt > 0.2)
            {
                double r = (total - lastBytes) / finalDt;
                if (r > peakRate) peakRate = r;
            }
            peak = peakRate;
            if (errors.Count > 0 && total == 0)
            {
                lock (errors)
                {
                    Console.WriteLine("      [err] " + (errors.Count == 1 ? errors[0] :
                        errors[0] + " (+" + (errors.Count - 1) + " more)"));
                }
            }
        }

        // Upload benchmark: `streams` parallel HTTP POSTs of `bytesPerStream`
        // zero bytes each through the local HTTP tunnel. Mirror of
        // BenchDownload; reports aggregate bytes accepted and wall time.
        private static void BenchUpload(int streams, long bytesPerStream,
                                        out long total, out double secs)
        {
            long totalBytes = 0;
            var errors = new List<string>();
            var threads = new List<Thread>();
            Stopwatch sw = new Stopwatch();
            sw.Start();
            for (int i = 0; i < streams; i++)
            {
                Thread th = new Thread(delegate()
                {
                    long got = 0;
                    try
                    {
                        HttpWebRequest req = (HttpWebRequest)WebRequest.Create(
                            "https://speed.cloudflare.com/__up");
                        req.Proxy = new WebProxy("127.0.0.1", 8118);
                        req.Method = "POST";
                        req.ContentType = "application/octet-stream";
                        req.ContentLength = bytesPerStream;
                        req.Timeout = 180000;
                        req.ReadWriteTimeout = 180000;
                        req.UserAgent = "torjet-speedtest/1.0";
                        byte[] buf = new byte[64 * 1024];
                        using (Stream rs = req.GetRequestStream())
                        {
                            long sent = 0;
                            while (sent < bytesPerStream)
                            {
                                int chunk = (int)Math.Min((long)buf.Length, bytesPerStream - sent);
                                rs.Write(buf, 0, chunk);
                                sent += chunk;
                            }
                        }
                        using (WebResponse resp = req.GetResponse())
                        {
                            int code = (int)((HttpWebResponse)resp).StatusCode;
                            if (code >= 200 && code < 300) got = bytesPerStream;
                        }
                    }
                    catch (Exception ex)
                    {
                        lock (errors) errors.Add(ex.Message);
                    }
                    Interlocked.Add(ref totalBytes, got);
                });
                th.IsBackground = true;
                threads.Add(th);
                th.Start();
            }
            foreach (Thread th in threads) th.Join();
            sw.Stop();
            total = Interlocked.Read(ref totalBytes);
            secs = sw.Elapsed.TotalSeconds;
        }

        private static void RunBench(int mode, int iters, int[] streamCounts, string csvPath)
        {
            string err;
            bool aborted = false;
            Process proc = StartTorAndWait(mode, ResolveStrategy(), true, null, out err, out aborted);
            if (proc == null)
            {
                if (aborted) { Cleanup(); return; }
                Console.WriteLine("[x] " + err);
                Cleanup();
                return;
            }
            try
            {
                ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;
                ServicePointManager.DefaultConnectionLimit = 64;
            }
            catch { }

            Console.WriteLine("bootstrap OK. Warming up 30s (building conflux legs)...");
            Thread.Sleep(30000);
            ProbeBenchUrl();
            if (benchUrl == null)
            {
                Console.WriteLine("[x] aborting bench: no reachable speed endpoint.");
                Cleanup();
                return;
            }

            string variant = Environment.GetEnvironmentVariable("BENCH_VARIANT") ?? "";
            bool writeHeader = !File.Exists(csvPath) || new FileInfo(csvPath).Length == 0;
            var rows = new StringBuilder();
            if (writeHeader)
                rows.AppendLine("ts,variant,mode,streams,avg_mbps,peak_mbps,total_bytes,up_avg_mbps,up_total_bytes,exit_fp,exit_bw,conflux_sets,conflux_legs");

            foreach (int sc in streamCounts)
            {
                for (int i = 0; i < iters; i++)
                {
                    Console.WriteLine("  [" + (variant.Length > 0 ? variant : ModeNames[mode]) +
                                      "] streams=" + sc + " iter=" + (i + 1) + " ...");
                    long total, upTotal;
                    double secs, peak, upSecs;
                    BenchDownload(sc, 10L * 1024 * 1024, out total, out secs, out peak);
                    double avg = secs > 0 ? total / secs : 0;
                    BenchUpload(sc, 10L * 1024 * 1024, out upTotal, out upSecs);
                    double upAvg = upSecs > 0 ? upTotal / upSecs : 0;
                    Console.WriteLine("      down avg " + FormatSpeed(avg) + "  peak " + FormatSpeed(peak) +
                                      "  in " + secs.ToString("0.0") + " s   |   up avg " +
                                      FormatSpeed(upAvg) + "  in " + upSecs.ToString("0.0") + " s");
                    int cSets, cLegs;
                    string exit = ConfluxInfo(out cSets, out cLegs);
                    string bw = ExitBandwidth(exit);
                    rows.AppendLine(string.Join(",",
                        DateTime.UtcNow.ToString("yyyy-MM-dd HH:mm:ss"),
                        Csv(variant), ModeNames[mode], sc.ToString(),
                        (avg / (1024 * 1024)).ToString("0.000"),
                        (peak / (1024 * 1024)).ToString("0.000"),
                        total.ToString(),
                        (upAvg / (1024 * 1024)).ToString("0.000"),
                        upTotal.ToString(), exit, bw, cSets.ToString(), cLegs.ToString()));
                }
            }
            try { File.AppendAllText(csvPath, rows.ToString(), new UTF8Encoding(false)); }
            catch (Exception ex) { Console.WriteLine("[x] failed to write CSV: " + ex.Message); }
            Console.WriteLine("CSV appended to " + csvPath);

            int s2, l2;
            string e2 = ConfluxInfo(out s2, out l2);
            Console.WriteLine("conflux at end: " + s2 + " set(s), " + l2 + " leg(s), exit " + e2);
            Cleanup();
        }

        private static string Csv(string s)
        {
            if (s.IndexOfAny(new[] { ',', '"', '\n', '\r' }) < 0) return s;
            return "\"" + s.Replace("\"", "\"\"") + "\"";
        }

        private static int[] ParseInts(string s)
        {
            var list = new List<int>();
            foreach (string p in s.Split(','))
            {
                int n;
                if (int.TryParse(p.Trim(), out n) && n >= 1) list.Add(n);
            }
            if (list.Count == 0) list.Add(1);
            return list.ToArray();
        }

        private static int StopTor()
        {
            Process p = FindTor();
            if (p != null)
            {
                try { p.Kill(); p.WaitForExit(5000); } catch { }
                SetSystemProxy(false);
                Console.WriteLine("Tor stopped; system proxy restored.");
            }
            else
            {
                Console.WriteLine("No tor from this folder is running.");
            }
            return 0;
        }

        // --- startup port check --------------------------------------------
        // If the TorJet ports are already occupied, a previous tor instance is
        // still running: stop it (and any leftover TUN/system proxy), then carry
        // on with a fresh start instead of refusing to launch.
        private static bool TcpPortBusy(int port)
        {
            TcpListener l = null;
            try
            {
                l = new TcpListener(IPAddress.Loopback, port);
                l.Start();
                return false;
            }
            catch (SocketException) { return true; }
            finally
            {
                if (l != null) try { l.Stop(); } catch { }
            }
        }

        private static bool UdpPortBusy(int port)
        {
            try
            {
                using (UdpClient u = new UdpClient(new IPEndPoint(IPAddress.Loopback, port)))
                { }
                return false;
            }
            catch (SocketException) { return true; }
        }

        private static bool PreviousRunActive()
        {
            foreach (int p in TcpPorts)
                if (TcpPortBusy(p)) return true;
            if (UdpPortBusy(UdpDnsPort)) return true;
            return false;
        }

        private static void StopPreviousRun()
        {
            Process running = FindTor();
            bool prev = running != null || PreviousRunActive();
            if (!prev && !TunActive()) return;

            Console.WriteLine("  A previous TorJet run is still active - stopping it.");

            if (TunActive())
            {
                Console.WriteLine("  Stopping previous TUN...");
                try { File.WriteAllText(TunStopFile, "stop", new UTF8Encoding(false)); } catch { }
                for (int i = 0; i < 16 && TunActive(); i++) Thread.Sleep(500);
                if (TunActive())
                    try { SpawnElevated("off", true); } catch { }
            }

            if (prev)
            {
                var victims = new List<Process>();
                try
                {
                    foreach (Process p in Process.GetProcessesByName("tor"))
                    {
                        try
                        {
                            string path;
                            try { path = p.MainModule.FileName; }
                            catch { path = null; }
                            if (path == null ||
                                StringComparer.OrdinalIgnoreCase.Equals(
                                    Path.GetFullPath(path), Path.GetFullPath(TorExe)))
                                victims.Add(p);
                        }
                        catch { }
                    }
                }
                catch { }
                if (running != null && !victims.Exists(v => v.Id == running.Id))
                    victims.Add(running);
                foreach (Process p in victims)
                {
                    try
                    {
                        Console.WriteLine("  Stopping previous tor (PID " + p.Id + ")...");
                        p.Kill();
                        p.WaitForExit(5000);
                    }
                    catch { }
                }
                Thread.Sleep(1500);
            }

            SetSystemProxy(false);
        }

        // --- watchdog: auto-restart a hung tunnel -----------------------------
        // Independent probe every WatchdogProbeIntervalS seconds once the
        // post-bootstrap grace window has passed. After WatchdogFailuresToRestart
        // consecutive failures it kills tor so the session's restart loop
        // rebuilds monitor, keep-alive and TUN. --no-watchdog disables it.
        private static bool watchdogEnabled = true;
        private const int WatchdogProbeIntervalS = 15;
        private const int WatchdogFailuresToRestart = 4;
        private static volatile bool watchdogStop = true;
        private static volatile bool watchdogTriggered;

        private static void WatchdogLoop()
        {
            // Grace while conflux legs build: fresh boots are legitimately slow.
            Thread.Sleep(TimeSpan.FromSeconds(warmupRelaxSeconds));
            int fails = 0, probe = 0;
            while (!watchdogStop)
            {
                Thread.Sleep(TimeSpan.FromSeconds(WatchdogProbeIntervalS));
                if (watchdogStop) return;
                Process p = torProc;
                if (p == null) return;
                try { p.Refresh(); if (p.HasExited) return; } catch { return; }
                PingTarget t = PingTargets[probe++ % PingTargets.Length];
                long ms;
                int r = PingSocks(t.Host, t.Path, out ms);
                fails = (r == 1) ? 0 : fails + 1;
                if (fails >= WatchdogFailuresToRestart)
                {
                    watchdogTriggered = true;
                    Log("watchdog: " + fails + " consecutive failed probes (" +
                        t.Host + ") - tor appears hung, killing for auto-restart");
                    Console.WriteLine();
                    Console.WriteLine("  [watchdog] tunnel unresponsive (" + fails +
                                      " failed probes) - restarting tor...");
                    try { p.Kill(); } catch { }
                    return;
                }
            }
        }

        private static void StartWatchdog()
        {
            if (!watchdogEnabled) return;
            watchdogStop = false;
            watchdogTriggered = false;
            Thread wd = new Thread(WatchdogLoop) { IsBackground = true };
            wd.Start();
        }

        // --- auto mode: race three transports, keep the fastest --------------
        // Spawns vanilla / obfs4 / webtunnel tor instances side by side, each
        // with its own ports and DataDirectory, and reports every progress
        // change. The first instance to reach 100% wins; the losers are killed
        // and the winner restarts on the primary ports reusing its cached
        // directory, so the final bootstrap takes seconds.
        private sealed class AutoRacer
        {
            public string Name;
            public int Mode;
            public string Dir;
            public string TorrcFile;
            public int Socks, Keep, Http, Dns, Ctrl;
            public Process Proc;
            public int LastPct = -1;
            public string LastTag = "";
            public bool Alive = true;
        }

        // SocksPort/HTTPTunnelPort/DNSPort/ControlPort/Log are cumulative torrc
        // options: appending overrides would ADD listeners on the primary
        // ports instead of replacing them. Racer configs therefore get the
        // template with every listener line stripped, then their own block.
        private static string StripListenerLines(string content)
        {
            var keep = new List<string>();
            foreach (string raw in content.Split('\n'))
            {
                string t = raw.Trim();
                bool drop = t.StartsWith("SocksPort ", StringComparison.OrdinalIgnoreCase) ||
                            t.StartsWith("HTTPTunnelPort ", StringComparison.OrdinalIgnoreCase) ||
                            t.StartsWith("DNSPort ", StringComparison.OrdinalIgnoreCase) ||
                            t.StartsWith("ControlPort ", StringComparison.OrdinalIgnoreCase) ||
                            t.StartsWith("Log ", StringComparison.OrdinalIgnoreCase) ||
                            t.StartsWith("LogNoticeFile ", StringComparison.OrdinalIgnoreCase);
                if (!drop) keep.Add(raw.TrimEnd('\r'));
            }
            return string.Join("\n", keep);
        }

        private static void AutoKillAll(List<AutoRacer> racers)
        {
            foreach (AutoRacer r in racers)
            {
                try
                {
                    if (r.Proc != null && !r.Proc.HasExited)
                    {
                        r.Proc.Kill();
                        r.Proc.WaitForExit(3000);
                    }
                }
                catch { }
                r.Alive = false;
            }
        }

        private static void CopyDirectory(string src, string dst)
        {
            Directory.CreateDirectory(dst);
            foreach (string f in Directory.GetFiles(src))
            {
                try { File.Copy(f, Path.Combine(dst, Path.GetFileName(f)), true); }
                catch { }
            }
            foreach (string d in Directory.GetDirectories(src))
            {
                try { CopyDirectory(d, Path.Combine(dst, Path.GetFileName(d))); }
                catch { }
            }
        }

        private static string AutoRacerLog(AutoRacer r)
        {
            return Path.Combine(DataDir, r.Dir, "tor.log");
        }

        private static string AutoRacerCookie(AutoRacer r)
        {
            return Path.Combine(DataDir, r.Dir, "control_auth_cookie");
        }

        private static string AutoPad(string s)
        {
            return s.Length >= 9 ? s : s + new string(' ', 9 - s.Length);
        }

        private static string FirstLine(string s)
        {
            if (string.IsNullOrEmpty(s)) return "(no details)";
            int nl = s.IndexOf('\n');
            return nl > 0 ? s.Substring(0, nl).TrimEnd() : s.TrimEnd();
        }

        // Runs the race. Returns true with winnerMode set when one transport
        // reached 100% and its cache has been moved to the primary data dir.
        private static Action<string> autoLineSink;
        private static volatile bool autoAbort;
        private static void AutoEmit(string line)
        {
            Action<string> s = autoLineSink;
            if (s != null) s(line);
            else Console.WriteLine(line);
        }

        private static bool AutoRace(int strategy, out int winnerMode, out string raceError)
        {
            return AutoRace(strategy, out winnerMode, out raceError, null, null);
        }

        // lineSink (null = console) receives every [auto] event line; progress
        // (null = skip) is called each poll with the best alive racer's
        // percentage and name+tag, for GUI rings.
        private static bool AutoRace(int strategy, out int winnerMode, out string raceError,
                                     Action<string> lineSink, Action<int, string> progress)
        {
            autoLineSink = lineSink;
            autoAbort = false;
            winnerMode = -1;
            raceError = null;
            string[] names = { "vanilla", "obfs4", "webtunnel" };
            string[] suffixes = { "v", "o", "w" };
            var racers = new List<AutoRacer>();
            for (int i = 0; i < 3; i++)
            {
                AutoRacer r = new AutoRacer();
                r.Name = names[i];
                r.Mode = i; // ModeNames: vanilla, obfs4, webtunnel, ...
                r.Dir = "data-" + suffixes[i];
                r.TorrcFile = "torrc-auto-" + names[i];
                int basePort = 9150 + i * 100;
                r.Socks = basePort;
                r.Ctrl = basePort + 1;
                r.Keep = basePort + 2;
                r.Http = 8150 + i * 100;
                r.Dns = 61530 + i * 1000;
                racers.Add(r);
            }

            foreach (AutoRacer r in racers)
            {
                if (TcpPortBusy(r.Socks) || TcpPortBusy(r.Ctrl) ||
                    TcpPortBusy(r.Http) || TcpPortBusy(r.Keep))
                {
                    raceError = "race port " + r.Ctrl + "/" + r.Socks + " (" + r.Name + ") is busy";
                    return false;
                }
                if (UdpPortBusy(r.Dns))
                {
                    raceError = "race DNS port " + r.Dns + " (" + r.Name + ") is busy";
                    return false;
                }
            }

            AutoEmit("[auto] racing vanilla / obfs4 / webtunnel (strategy " +
                              StrategyNames[Math.Max(0, Math.Min(StrategyNames.Length - 1, strategy))] + ")");

            foreach (AutoRacer r in racers)
            {
                int bc;
                string content = BuildTorrc(r.Mode, strategy, out bc);
                if (content == null)
                {
                    raceError = "failed to build torrc for " + r.Name;
                    AutoKillAll(racers);
                    return false;
                }
                content = StripListenerLines(content);
                content += "\r\n\r\n# --- auto race overrides: " + r.Name + " ---\r\n" +
                           "DataDirectory " + r.Dir + "\r\n" +
                           "Log notice file " + r.Dir + @"\tor.log" + "\r\n" +
                           "SocksPort 127.0.0.1:" + r.Socks + " IsolateSOCKSAuth\r\n" +
                           "SocksPort 127.0.0.1:" + r.Keep + " NoIsolateSOCKSAuth\r\n" +
                           "HTTPTunnelPort 127.0.0.1:" + r.Http + "\r\n" +
                           "DNSPort 127.0.0.1:" + r.Dns + "\r\n" +
                           "ControlPort 127.0.0.1:" + r.Ctrl + "\r\n";
                File.WriteAllText(Path.Combine(DataDir, r.TorrcFile), content, new UTF8Encoding(false));
                Directory.CreateDirectory(Path.Combine(DataDir, r.Dir));
            }

            foreach (AutoRacer r in racers)
            {
                ProcessStartInfo psi = new ProcessStartInfo
                {
                    FileName = TorExe,
                    Arguments = "-f \"" + r.TorrcFile + "\"",
                    WorkingDirectory = DataDir,
                    UseShellExecute = false,
                    CreateNoWindow = true
                };
                try
                {
                    r.Proc = Process.Start(psi);
                    AutoEmit("[auto] " + AutoPad(r.Name) + " started (PID " + r.Proc.Id +
                                      ", socks " + r.Socks + ")");
                }
                catch (Exception ex)
                {
                    r.Alive = false;
                    AutoEmit("[auto] " + AutoPad(r.Name) + " failed to start: " + ex.Message);
                }
            }

            AutoRacer winner = null;
            DateTime started = DateTime.UtcNow;
            DateTime lastSnapshot = DateTime.UtcNow;
            while (winner == null)
            {
                if (DateTime.UtcNow - started > TimeSpan.FromMinutes(10))
                {
                    raceError = "10-minute timeout";
                    AutoKillAll(racers);
                    autoLineSink = null;
                    return false;
                }
                try
                {
                    if (autoAbort ||
                        (Console.KeyAvailable && Console.ReadKey(true).Key == ConsoleKey.C))
                    {
                        raceError = "aborted by user";
                        AutoKillAll(racers);
                        autoLineSink = null;
                        return false;
                    }
                }
                catch
                {
                    if (autoAbort)
                    {
                        raceError = "aborted by user";
                        AutoKillAll(racers);
                        autoLineSink = null;
                        return false;
                    }
                }
                Thread.Sleep(1500);

                int aliveCount = 0;
                int bestPct = -1;
                string bestInfo = "";
                foreach (AutoRacer r in racers)
                {
                    if (!r.Alive) continue;
                    try { r.Proc.Refresh(); r.Alive = !r.Proc.HasExited; }
                    catch { r.Alive = false; }
                    if (!r.Alive)
                    {
                        string tail = string.Join(" | ",
                            ReadLogTailFile(AutoRacerLog(r), 900));
                        AutoEmit("[auto] " + AutoPad(r.Name) + " DIED (code " +
                            r.Proc.ExitCode + ") " + FirstLine(tail));
                        continue;
                    }
                    aliveCount++;
                    int pct; string tag, summ;
                    if (BootstrapPhaseFor(r.Ctrl, AutoRacerLog(r), AutoRacerCookie(r),
                                          out pct, out tag, out summ))
                    {
                        if (pct != r.LastPct)
                        {
                            r.LastPct = pct;
                            r.LastTag = tag ?? "";
                            AutoEmit("[auto] " + AutoPad(r.Name) + " " + pct + "% " + r.LastTag);
                            if (pct >= 100) winner = r;
                        }
                        if (pct > bestPct)
                        {
                            bestPct = pct;
                            bestInfo = r.Name + " " + r.LastTag;
                        }
                    }
                }
                if (progress != null && bestPct >= 0)
                    progress(bestPct, bestInfo);
                if (winner != null) break;
                if (aliveCount == 0)
                {
                    raceError = "all three racers died";
                    autoLineSink = null;
                    return false;
                }
                if (DateTime.UtcNow - lastSnapshot > TimeSpan.FromSeconds(15))
                {
                    lastSnapshot = DateTime.UtcNow;
                    string s1 = racers[0].Alive ? (racers[0].LastPct < 0 ? "?" : racers[0].LastPct + "%") : "dead";
                    string s2 = racers[1].Alive ? (racers[1].LastPct < 0 ? "?" : racers[1].LastPct + "%") : "dead";
                    string s3 = racers[2].Alive ? (racers[2].LastPct < 0 ? "?" : racers[2].LastPct + "%") : "dead";
                    AutoEmit("[auto] snapshot   vanilla " + s1 + " | obfs4 " + s2 +
                                      " | webtunnel " + s3);
                }
            }

            AutoEmit("[auto] WINNER = " + winner.Name +
                              " — stopping the other two…");
            foreach (AutoRacer r in racers)
            {
                if (r != winner)
                {
                    try { if (r.Proc != null && !r.Proc.HasExited) { r.Proc.Kill(); r.Proc.WaitForExit(3000); } }
                    catch { }
                    r.Alive = false;
                }
            }
            // The winner is stopped too: its cache moves to the primary data
            // directory and the standard single-core start takes over.
            try { if (winner.Proc != null && !winner.Proc.HasExited) { winner.Proc.Kill(); winner.Proc.WaitForExit(3000); } }
            catch { }
            Thread.Sleep(800);

            AutoEmit("[auto] switching " + winner.Name + " to primary ports (9050/8118)…");
            try
            {
                string dst = Path.Combine(DataDir, "data");
                CopyDirectory(Path.Combine(DataDir, winner.Dir), dst);
                try { File.Delete(Path.Combine(dst, "lock")); } catch { }
            }
            catch (Exception ex)
            {
                Log("auto: cache copy failed (" + ex.Message + ") — cold bootstrap");
            }
            winnerMode = winner.Mode;
            autoLineSink = null;
            return true;
        }

        // Runs one Tor session: writes torrc, boots tor with a live progress
        // bar, then serves the P/T/S/C keys until the user presses C or tor
        // dies. A hung tunnel is detected by the watchdog and automatically
        // restarted (up to 3 attempts, TUN restored afterwards).
        // Returns 0 (clean exit), 1 (error) or 2 (return to main menu).
        private static int RunTorSession(int mode, int strategy,
                                         bool genOnly, bool bootstrapOnly, string autoMode,
                                         bool menuReturn, bool raceStart)
        {
            if (!File.Exists(TorExe))
            {
                Console.WriteLine("[x] tor.exe not found in " + DataDir);
                WaitForKey();
                return 1;
            }
            if (mode < 0)
            {
                mode = ReadLastMode();
                if (mode < 0) mode = 1; // obfs4 — only used when the race is off
            }
            if (genOnly)
            {
                if (!WriteTorrc(mode, strategy)) { WaitForKey(); return 1; }
                Console.WriteLine("torrc written only (test mode, tor not started): " + Torrc);
                return 0;
            }

            string startErr;
            bool aborted = false;
            bool tunWasOn = false;
            bool showBanners = true;
            for (int attempt = 1; ; attempt++)
            {
                watchdogStop = true;   // no probing while bootstrapping
                if (raceStart)
                {
                    int winnerMode;
                    string raceErr;
                    if (!AutoRace(strategy, out winnerMode, out raceErr))
                    {
                        Console.WriteLine("[x] auto race failed: " + raceErr);
                        Cleanup();
                        cleaned = false;
                        return menuReturn ? 2 : 1;
                    }
                    mode = winnerMode;
                    AutoEmit("[auto] winner mode: " + ModeNames[mode]);
                }
                torProc = StartTorAndWait(mode, strategy, true, null, out startErr, out aborted);
                if (torProc == null)
                {
                    if (aborted)
                    {
                        Console.WriteLine();
                        Console.WriteLine("  Stopping Tor...");
                        Cleanup();
                        cleaned = false;
                        Console.WriteLine("  Tor stopped; system proxy restored.");
                        Console.WriteLine();
                        return 2;
                    }
                    Console.WriteLine("[x] " + startErr);
                    Cleanup();
                    cleaned = false;
                    if (menuReturn)
                    {
                        Console.WriteLine();
                        Console.WriteLine("Press any key to return to the menu...");
                        try { Console.ReadKey(true); } catch { }
                        return 2;
                    }
                    WaitForKey();
                    return 1;
                }

                if (showBanners)
                {
                    Console.WriteLine();
                    Console.WriteLine("Bootstrapped 100% - Tor is UP.");
                    Console.WriteLine();
                    showBanners = false;
                }
                else
                {
                    Console.WriteLine();
                    Console.WriteLine("Bootstrapped 100% - Tor is UP (auto-restart " + attempt + ").");
                    Console.WriteLine();
                }

                if (bootstrapOnly)
                {
                    Console.WriteLine("Test mode: stopping tor (no proxy change).");
                    Cleanup();
                    return 0;
                }

                circuitWatchStop = false;
                circuitWatchWarmup = true;
                if (circuitWatchEnabled)
                {
                    Thread watcher = new Thread(CircuitWatchLoop) { IsBackground = true };
                    watcher.Start();
                    Log("circuit monitor: watching every " + watchIntervalS +
                        " s; weak legs (top " + watchRttPct + "% of all linked legs by RTT, " +
                        "globally across every set) are closed after " + watchStrikes +
                        " strikes; " +
                        "stuck-unlinked after " + watchUnlinkedStrikes +
                        " passes and " + watchUnlinkedGraceS + " s old; " +
                        "max " + watchMaxPerPass + " close(s)/pass (cooldown " +
                        watchCooldownS + " s, relaxed during warmup).");
                }

                // Start the permanent keep-alive (1 request/s through the real
                // SOCKS proxy) and show the menu right away. The monitor keeps its
                // relaxed cooldown for a short window after bootstrap while the
                // first conflux legs build, then enforces the normal gap.
                if (keepAliveEnabled)
                    StartKeepAlive();
                else
                    Log("keep-alive: disabled by setting (data\\keepalive.txt)");
                Thread warmupEnd = new Thread(delegate()
                {
                    Thread.Sleep(TimeSpan.FromSeconds(warmupRelaxSeconds));
                    circuitWatchWarmup = false;
                }) { IsBackground = true };
                warmupEnd.Start();

                bool proxyOn = false;
                if (attempt == 1)
                {
                    if (autoMode == "proxy")
                    {
                        proxyOn = true;
                        SetSystemProxy(true);
                        Console.WriteLine("  System proxy ON  (127.0.0.1:8118)");
                    }
                    else if (autoMode == "tun")
                    {
                        if (TunActive())
                            Console.WriteLine("  TUN already ON");
                        else
                            ToggleTun();
                    }
                }
                else if (tunWasOn && !TunActive())
                {
                    Console.WriteLine("  [watchdog] restoring TUN mode...");
                    ToggleTun();
                }
                tunWasOn = TunActive();

                if (attempt == 1)
                {
                    Console.WriteLine("  D   conflux details");
                    Console.WriteLine("  L   view log");
                    Console.WriteLine("  S   speed test");
                    Console.WriteLine("  A   add a leg to a set");
                    Console.WriteLine("  K   keep-alive report");
                    Console.WriteLine("  J   keep-alive on/off");
                    Console.WriteLine();
                    Console.WriteLine("\u2705\u2705\u2705\u2705\u2705\u2705\u2705\u2705\u2705\u2705\u2705\u2705\u2705\u2705\u2705\u2705");
                    Console.WriteLine("  T    :     On / Off  TUN mode");
                    Console.WriteLine("  P    :     On / Off  system proxy");
                    Console.WriteLine("  C    :     Stop Tor, back to menu");
                    Console.WriteLine();
                }
                StartWatchdog();

                int exitKind = 0; // 0 = tor really exited, 1 = watchdog restart
                while (true)
                {
                    bool alive = true;
                    if (torProc != null)
                    {
                        try { torProc.Refresh(); alive = !torProc.HasExited; }
                        catch { alive = false; }
                    }
                    if (!alive)
                    {
                        if (!watchdogTriggered)
                            Console.WriteLine("[x] tor exited with code " +
                                (torProc != null ? torProc.ExitCode : -1) + ".");
                        exitKind = watchdogTriggered ? 1 : 0;
                        break;
                    }
                    try
                    {
                        if (Console.KeyAvailable)
                        {
                            ConsoleKeyInfo ki = Console.ReadKey(true);
                            if (ki.Key == ConsoleKey.P)
                            {
                                proxyOn = !proxyOn;
                                SetSystemProxy(proxyOn);
                                Console.WriteLine("  System proxy " + (proxyOn ? "ON  (127.0.0.1:8118)" : "OFF"));
                            }
                            else if (ki.Key == ConsoleKey.S)
                            {
                                SpeedTestMenu();
                            }
                            else if (ki.Key == ConsoleKey.A)
                            {
                                lock (consoleLock) AddConfluxLeg(null);
                            }
                            else if (ki.Key == ConsoleKey.L)
                            {
                                lock (consoleLock) ViewLog();
                            }
                            else if (ki.Key == ConsoleKey.D)
                            {
                                lock (consoleLock) ConfluxStatus(true);
                            }
                            else if (ki.Key == ConsoleKey.K)
                            {
                                lock (consoleLock) ShowKeepAliveReport();
                            }
                            else if (ki.Key == ConsoleKey.J)
                            {
                                lock (consoleLock) ToggleKeepAlive();
                            }
                            else if (ki.Key == ConsoleKey.V)
                            {
                                lock (consoleLock) ViewLog();
                            }
                            else if (ki.Key == ConsoleKey.T)
                            {
                                ToggleTun();
                                tunWasOn = TunActive();
                            }
                            else if (ki.Key == ConsoleKey.C)
                            {
                                Console.WriteLine();
                                Console.WriteLine("  Stopping Tor...");
                                Cleanup();
                                cleaned = false;
                                torProc = null;
                                Console.WriteLine("  Tor stopped; system proxy restored.");
                                Console.WriteLine();
                                return 2;
                            }
                        }
                    }
                    catch { }
                    Thread.Sleep(150);
                }

                if (exitKind != 1)
                    break;   // tor genuinely exited -> normal teardown below

                // Watchdog path: rebuild the session without touching the
                // system-proxy state. Snapshot TUN now - the keeper dies with
                // tor, so this is the last reliable moment to observe it.
                tunWasOn = TunActive();
                Log("watchdog: restarting tor (attempt " + attempt + ")");
                circuitWatchStop = true;
                watchdogStop = true;
                StopKeepAlive();
                DnsCacheStop();
                try { torProc.Kill(); torProc.WaitForExit(5000); } catch { }
                for (int i = 0; i < 30 && PreviousRunActive(); i++) Thread.Sleep(500);
                try { if (File.Exists(LockFile)) File.Delete(LockFile); } catch { }
                cleaned = false;
                if (attempt >= 3)
                {
                    Console.WriteLine("[x] watchdog gave up after 3 restart attempts.");
                    break;
                }
            }

            Cleanup();
            cleaned = false;
            Console.WriteLine("Tor stopped; system proxy restored.");
            WaitForKey();
            return 0;
        }

        // --- version / background update check ------------------------------
        // Compares dotted versions (1.2.3); non-numeric parts are treated as 0.
        private static int CompareVersions(string a, string b)
        {
            string[] pa = a.Split('.');
            string[] pb = b.Split('.');
            int n = Math.Max(pa.Length, pb.Length);
            for (int i = 0; i < n; i++)
            {
                int x = i < pa.Length ? VersionPart(pa[i]) : 0;
                int y = i < pb.Length ? VersionPart(pb[i]) : 0;
                if (x != y) return x.CompareTo(y);
            }
            return 0;
        }

        private static int VersionPart(string s)
        {
            int v;
            if (int.TryParse(s, out v)) return v;
            Match m = Regex.Match(s, @"^\d+");
            return m.Success ? int.Parse(m.Value) : 0;
        }

        // Queries the GitHub latest release; prints the download link when a
        // newer version than the embedded one exists.
        private static void CheckForUpdates()
        {
            try { ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12; }
            catch { }
            try
            {
                HttpWebRequest req = (HttpWebRequest)WebRequest.Create(
                    "https://api.github.com/repos/Delta-Kronecker/TorJet/releases/latest");
                req.UserAgent = "torjet-update-check/" + TorJetVersion.App;
                req.Timeout = 8000;
                req.ReadWriteTimeout = 8000;
                using (WebResponse resp = req.GetResponse())
                using (StreamReader sr = new StreamReader(resp.GetResponseStream()))
                {
                    Match m = Regex.Match(sr.ReadToEnd(), "\"tag_name\"\\s*:\\s*\"([^\"]+)\"");
                    if (m.Success)
                    {
                        string latest = m.Groups[1].Value.TrimStart('v', 'V');
                        if (CompareVersions(latest, TorJetVersion.App) > 0)
                        {
                            updatePromptShown = true;
                            Console.WriteLine();
                            Console.WriteLine("  New TorJet version available: v" + latest +
                                              " (you have v" + TorJetVersion.App + ")");
                            Console.WriteLine("      Download: https://github.com/Delta-Kronecker/TorJet/releases/latest");
                            Console.WriteLine();
                        }
                    }
                }
            }
            catch { }
        }

        private static void UpdateCheckLoop()
        {
            while (true)
            {
                if (!updatePromptShown) CheckForUpdates();
                Thread.Sleep(TimeSpan.FromMinutes(30));
            }
        }

        [System.Runtime.InteropServices.DllImport("kernel32.dll")]
        private static extern bool AttachConsole(int pid);
        [System.Runtime.InteropServices.DllImport("kernel32.dll")]
        private static extern bool AllocConsole();
        [System.Runtime.InteropServices.DllImport("kernel32.dll")]
        private static extern bool FreeConsole();
        private static bool consoleAttached;
        private static bool consoleOwned;

        // The launcher is built as a windowed exe (no console flash on GUI
        // launch). CLI invocations attach to the parent terminal; when there
        // is none (e.g. mintty), a fresh console is allocated so output and
        // the interactive menus still work. Only a console we allocated may
        // be retitled/re-encoded — never the parent terminal.
        private static void AttachParentConsole()
        {
            try
            {
                if (AttachConsole(-1)) { consoleAttached = true; return; }
                if (AllocConsole())
                {
                    consoleAttached = true;
                    consoleOwned = true;
                }
            }
            catch { }
        }

        private static void DetachConsole()
        {
            try
            {
                Console.Out.Flush();
                Console.Error.Flush();
            }
            catch { }
            if (consoleAttached)
            {
                try { FreeConsole(); } catch { }
                Thread.Sleep(60);
            }
        }

        private static int Main(string[] args)
        {
            // GUI when launched bare (double-click) or with --gui; the classic
            // console flows stay available for every other invocation and via
            // --cli. A bare GUI launch never shows a console window.
            bool forceCli = Array.Exists(args, delegate(string a) { return a == "--cli"; });
            bool wantGui = !forceCli &&
                           (args.Length == 0 || Array.Exists(args, delegate(string a) { return a == "--gui"; }));
            if (wantGui)
            {
                RunGui();
                return 0;
            }
            AttachParentConsole();
            int rc = MainCli(args);
            DetachConsole();
            return rc;
        }

        private static int MainCli(string[] args)
        {
            if (consoleOwned)
            {
                try { Console.Title = "TorJet"; } catch { }
                try { Console.OutputEncoding = Encoding.UTF8; } catch { }
            }
            // Recover the user's pre-TorJet proxy settings if a previous run
            // crashed while the TorJet system proxy was still enabled.
            LoadProxyBackup();
            Console.CancelKeyPress += delegate(object sender, ConsoleCancelEventArgs e)
            {
                e.Cancel = true;
                Cleanup();
                Environment.Exit(0);
            };
            AppDomain.CurrentDomain.ProcessExit += delegate(object sender, EventArgs e)
            {
                Cleanup();
            };

            Thread updater = new Thread(UpdateCheckLoop) { IsBackground = true };
            updater.Start();

            if (args.Length > 0 && args[0] == "--conflux-status")
            {
                return ConfluxStatus(true);
            }
            if (args.Length > 0 && args[0] == "--conflux-add")
            {
                return AddConfluxLeg(args.Length > 1 ? args[1] : null);
            }
            if (args.Length > 0 && args[0] == "--conflux-check")
            {
                int m = -1;
                for (int i = 1; i < args.Length; i++) { int mm = ParseMode(args[i]); if (mm >= 0) m = mm; }
                if (m < 0) m = ShowMenu();
                if (m < 0) { Console.WriteLine("[x] no mode selected."); return 1; }
                string err;
                bool aborted = false;
                Process p = StartTorAndWait(m, ResolveStrategy(), true, null, out err, out aborted);
                if (p == null) { if (aborted) { Cleanup(); return 1; } Console.WriteLine("[x] " + err); Cleanup(); return 1; }
                Console.WriteLine("bootstrap OK. Waiting 30s for conflux sets to build...");
                Thread.Sleep(30000);
                int code = ConfluxStatus(false);
                Cleanup();
                return code;
            }
            if (args.Length > 0 && args[0] == "--bench")
            {
                int bMode = -1;
                int iters = 3;
                int[] streams = { 1, 4, 8 };
                string csvPath = "bench.csv";
                for (int i = 1; i < args.Length; i++)
                {
                    if (args[i] == "--iters" && i + 1 < args.Length) { int.TryParse(args[++i], out iters); }
                    else if (args[i] == "--streams" && i + 1 < args.Length) { streams = ParseInts(args[++i]); }
                    else if (args[i] == "--csv" && i + 1 < args.Length) { csvPath = args[++i]; }
                    else { int mm = ParseMode(args[i]); if (mm >= 0) bMode = mm; }
                }
                if (bMode < 0) bMode = ShowMenu();
                if (bMode < 0) return 1;
                RunBench(bMode, iters, streams, csvPath);
                return 0;
            }
            if (args.Length > 0 && args[0] == "--newcircuit")
            {
                Console.WriteLine(ControlSend("SIGNAL NEWNYM")
                    ? "New identity requested (NEWNYM)."
                    : "No tor control port on 127.0.0.1:9051. Is tor running?");
                return 0;
            }
            if (args.Length > 0 && args[0] == "--stop")
            {
                return StopTor();
            }
            if (args.Length > 0 &&
                (args[0] == "--update-bridges" || args[0] == "--update" || args[0] == "-u"))
            {
                return UpdateBridges();
            }
            if (args.Length > 0 && args[0] == "--tun-off")
            {
                if (!TunActive())
                {
                    Console.WriteLine("TUN OFF");
                    return 0;
                }
                TurnTunOff();
                return TunActive() ? 1 : 0;
            }
            if (args.Length > 0 && args[0] == "--tun-status")
            {
                Console.WriteLine("TUN " + (TunActive() ? "ON" : "OFF"));
                return 0;
            }

            int mode = -1;
            int strategy = -1;
            bool bootstrapOnly = false;
            bool genOnly = false;
            bool newCircuit = false;
            bool raceStart = false;
            string autoMode = "";
            for (int i = 0; i < args.Length; i++)
            {
                string a = args[i];
                if (a == "--bootstrap-only" || a == "-t") bootstrapOnly = true;
                else if (a == "--gen-torrc-only") genOnly = true;
                else if (a == "--strategy" && i + 1 < args.Length) strategy = ParseStrategy(args[++i]);
                else if (a == "--newcircuit") newCircuit = true;
                else if (a == "auto" || a == "--auto") raceStart = true;
                else if (a == "--circuit-watch") circuitWatchEnabled = true;
                else if (a == "--no-circuit-watch") circuitWatchEnabled = false;
                else if (a == "--no-watchdog") watchdogEnabled = false;
                else if (a == "--watchdog") watchdogEnabled = true;
                else if (a == "--watch-rtt-pct" && i + 1 < args.Length) { int.TryParse(args[++i], out watchRttPct); }
                else if (a == "--watch-strikes" && i + 1 < args.Length) { int.TryParse(args[++i], out watchStrikes); }
                else if (a == "--watch-unlinked-strikes" && i + 1 < args.Length) { int.TryParse(args[++i], out watchUnlinkedStrikes); }
                else if (a == "--watch-unlinked-grace" && i + 1 < args.Length) { int.TryParse(args[++i], out watchUnlinkedGraceS); }
                else if (a == "--watch-max-per-pass" && i + 1 < args.Length) { int.TryParse(args[++i], out watchMaxPerPass); }
                else if (a == "--watch-interval" && i + 1 < args.Length) { int.TryParse(args[++i], out watchIntervalS); }
                else if (a == "--watch-cooldown" && i + 1 < args.Length) { int.TryParse(args[++i], out watchCooldownS); }
                else if (a == "proxy" || a == "--proxy") autoMode = "proxy";
                else if (a == "tun" || a == "--tun") autoMode = "tun";
                else
                {
                    int m = ParseMode(a);
                    if (m >= 0) { mode = m; continue; }
                    int s = ParseStrategy(a);
                    if (s >= 0) strategy = s;
                }
            }
            if (strategy >= 0) ApplyConfluxPresetForStrategy(strategy);
            if (newCircuit)
            {
                Console.WriteLine(ControlSend("SIGNAL NEWNYM")
                    ? "New identity requested (NEWNYM)."
                    : "No tor control port on 127.0.0.1:9051. Is tor running?");
                return 0;
            }
            if (mode < 0 && !raceStart)
            {
                while (true)
                {
                    ShowMainMenu(out mode, out strategy);
                    if (mode < 0) return 0;
                    int rc = RunTorSession(mode, strategy, genOnly, bootstrapOnly, autoMode, true, raceStart);
                    if (rc != 2) return rc;
                }
            }
            else
            {
                if (strategy < 0) strategy = ReadLastStrategy();
                if (strategy < 0) strategy = DefaultStrategy();
                while (true)
                {
                    int rc = RunTorSession(mode, strategy, genOnly, bootstrapOnly, autoMode, true, raceStart);
                    if (rc != 2) return rc;
                    ShowMainMenu(out mode, out strategy);
                    if (mode < 0) return 0;
                }
            }
        }
    }
}
